-- 2909 🏋️ Exercises from the book "spain-attacking-sessions-140-practices-from-goal-analysis-of-the-spanish-nationa" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'spain-attacking-sessions-140-practices-from-goal-analysis-of-the-spanish-nationa');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Slalom first touch and shoot, two goals', 'finishing', 'unopposed', 'in_possession', 32, 33, 'Attacking Inside the Penalty Area: Practice 1', NULL, 'Body shape on receiving, a directional first touch and accurate finishing in the box.', '25x25 yd square with a full goal and keeper at each end and 5 mannequins across the middle; one worker inside, 4 servers with balls round the outside.', 'Worker weaves through the mannequins, takes a pass from server 1, touches away with the left and shoots; then receives from 2 with a turning touch toward the other goal, then from 3 after rounding the end mannequin, then from 4 between mannequins, shooting each time. After 4 shots he swaps with a server.', 'Max 3 touches to shoot, then 2.', 'Start from the other side so each player works both directions (min 2 reps each side).', 'Open up and receive half-turned on the back foot; first touch out of the feet toward goal but kept close; accuracy over power.', '5 + 2 GK', 7, 7, '25 x 25 yards', 22.9, 22.9, NULL, true, true, true, NULL, 10),
  ('Called-number first touch finishing, 8 servers', 'finishing', 'unopposed', 'in_possession', 34, 34, 'Attacking Inside the Penalty Area: Practice 2', NULL, 'Quick recognition, directional first touch and finishing to either goal.', 'Same square with two goals and keepers, 7 mannequins inside and 8 numbered servers with balls spread round the outside.', 'Coach shouts a server''s number; the inside player reads where that server is, moves to get free, takes a directional touch and shoots at either goal. He works through all 8 balls then swaps with a server.', NULL, 'Servers stand in random order rather than numerical order.', 'Quality of perception, decision and execution rather than flat-out speed; anticipate and react early.', '9 + 2 GK', 11, 11, '25 x 25 yards', 22.9, 22.9, NULL, true, true, true, NULL, 20),
  ('Called-number touch and finish in box', 'finishing', 'unopposed', 'in_possession', 35, 35, 'Attacking Inside the Penalty Area: Practice 3', NULL, 'Body shape, directional first touch and finishing inside the penalty area.', 'Half pitch; 7 mannequins in the box, one worker inside, 5 numbered servers with balls outside the box, goal with keeper.', 'Coach calls a number; that server passes in, the worker takes a quality directional touch and shoots with his second. Five balls then swap with a server.', NULL, NULL, 'Accurate, well-weighted passes so the receiver can touch and finish quickly.', '6 + GK', 7, 7, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 30),
  ('6v6 quick finishing with 8 neutrals', 'small_sided_game', 'overload', 'in_possession', 36, 36, 'Attacking Inside the Penalty Area: Practice 4', NULL, 'Directional first touches and fast finishing in a small game.', '25x25 yd pitch with goals and keepers; 6v6 inside and 8 neutrals around the outside.', 'Game starts from a team or coach''s ball; neutrals join the team with the ball for a 13v5 outfield overload. Teams must get a shot off inside a time or touch limit set by the coach.', 'Finish within 6, 8 or 10 seconds, or within 6, 8 or 10 team touches; players unlimited (or 2-3) touches, neutrals 1 touch.', NULL, 'Overload the ball area to create space for a final pass, touch and shot.', '6v6 (+8) + 2 GK', 22, 22, '25 x 25 yards', 22.9, 22.9, NULL, true, true, true, NULL, 40),
  ('6v6 quick finishing, no neutrals', 'small_sided_game', 'opposed', 'in_possession', 37, 37, 'Attacking Inside the Penalty Area: Practice 5', NULL, 'Make space and shoot very quickly under even numbers.', '25x25 yd pitch, two goals with keepers, 6v6, neutrals removed.', 'Same game and time/touch limits as the previous practice but straight 6v6, so players must be sharper to free a shot.', 'Same time or touch limits as Practice 4.', NULL, 'Take any chance to touch half a yard clear and shoot; open body, receive and pass with the back foot; mix passes to feet and into space.', '6v6 + 2 GK', 14, 14, '25 x 25 yards', 22.9, 22.9, NULL, true, true, true, NULL, 50),
  ('Two-zone 6v6 with wide neutrals', 'small_sided_game', 'overload', 'in_possession', 38, 38, 'Attacking Inside the Penalty Area: Practice 6', NULL, 'Use wide support to overload and shoot quickly.', '30x20 yd pitch split into 2 halves, goal and keeper at each end; per half a 3v2 for attackers, plus 4 neutrals on the sides.', 'Keeper starts; the team on the ball uses neutrals and its 3 front players to score under time pressure. Everyone stays in their zone. Next attack starts from the other keeper.', 'Options: finish within 6-10 seconds; max 10 team touches; unlimited touches with neutrals 1 touch; defenders 2 touches, attackers 3, neutrals 1.', NULL, 'Use the wide neutrals to make the extra man and space to shoot.', '6v6 (+4) + 2 GK', 18, 18, '30 x 20 yards', 27.4, 18.3, NULL, true, true, true, NULL, 60),
  ('11v11 two-zone finishing game, double box', 'conditioned_game', 'opposed', 'in_possession', 39, 39, 'Attacking Inside the Penalty Area: Practice 7', NULL, 'Play into players in the box who touch directionally and shoot fast.', 'Area twice the penalty box split in 2 zones, goal at each end; 4-4-2 v 4-3-3, 4 per team in each zone plus 2 wide players per team beside the attacking half.', 'Normal game but players stay in their zone; wide players may only shoot or pass to each other once they carry the ball into the attacking zone.', 'Options: unlimited touches; defenders 2-3 touches; all 3 touches; defenders and wide players 3, attackers 2.', NULL, 'Feed the box players, who take good directional touches and shoot quickly, dribble at defenders or find a free teammate.', '11v11', 22, 22, 'Double penalty area, 2 zones', NULL, NULL, NULL, true, true, true, NULL, 70),
  ('One-touch third man run, 6 players', 'passing_unopposed', 'unopposed', 'in_possession', 42, 42, 'Attacking in and Around the Penalty Area (6 practices): Practice 1', NULL, 'One-touch passing, timing and movement built around the third-man run.', '6 players and 4 cones in a diamond-like shape, one ball.', 'Pattern 1: 1 plays 2, 2 plays 3, 1 runs forward as third man to take 3''s one-touch pass and plays 4; repeat from 4 back. Pattern 2: 1-2 between 1 and 2, then 1 passes to 3 and 2 runs across to get the return and plays 4; everyone rotates one spot.', 'One touch.', 'Run both patterns from both sides; coach changes the fixed players.', NULL, '6', 6, 6, NULL, NULL, NULL, NULL, false, false, false, NULL, 80),
  ('Third man run combination and shot', 'combination', 'unopposed', 'in_possession', 43, 43, 'Attacking in and Around the Penalty Area (6 practices): Practice 2', NULL, 'One-touch combinations with a third-man run ending in a shot.', '30x30 yd area, goal and keeper; 6 stations with 2 players each, forming two groups of 3 (one each side).', '1 passes to 2, who checks off his cone; 2 finds 3 who has dropped deep; 1 runs on toward goal and shoots off 3''s first-time pass. Group rotates one place and the other side goes.', NULL, NULL, 'Right angles and body shape for each pass; 2''s movement mimics losing a marker.', '12 + GK', 13, 13, '30 x 30 yards', 27.4, 27.4, NULL, true, true, true, NULL, 90),
  ('Third man run and shot, variation 2', 'combination', 'unopposed', 'in_possession', 44, 44, 'Attacking in and Around the Penalty Area (6 practices): Practice 3', NULL, 'Same as previous with a different passing sequence.', 'Same 30x30 yd set-up with 6 stations and a goal.', '1 plays 2, who sets back to 1; 1 then finds 3 who has gone deep; 2 sets off diagonally toward goal as third man and shoots from 3''s first-time pass.', NULL, NULL, NULL, '12 + GK', 13, 13, '30 x 30 yards', 27.4, 27.4, NULL, true, true, true, NULL, 100),
  ('3-zone 6v6 combination to support player', 'small_sided_game', 'overload', 'in_possession', 45, 45, 'Attacking in and Around the Penalty Area (6 practices): Practice 4', NULL, 'Quick combinations, third-man runs and finishing in a game.', '38x14 yd pitch in 3 zones (middle 14x14, end zones 12x14); 4v4 + 2 neutrals in the middle, each team has a support player in the end zone it attacks, goal and keeper each end.', 'Team on the ball (4+2 v 4) must string 6-8 passes, then pass into its support player; a middle player then makes a third-man run forward, takes the first-time lay-off and shoots.', 'Teams 2 touches in middle, 1 in end zones; neutrals and support players 1 touch.', 'Support player can swap with the shooter.', NULL, '6v6 (+2) + 2 GK', 16, 16, '38 x 14 yards', 34.7, 12.8, NULL, true, true, true, NULL, 110),
  ('3-zone 8v8 third man combination game', 'small_sided_game', 'overload', 'in_possession', 46, 46, 'Attacking in and Around the Penalty Area (6 practices): Practice 5', NULL, 'Combination play and third-man runs into a shot.', '3 zones, end zones 16 yd long; 6v6 + 2 neutrals in the middle, each team with an extra support player up front; reds in 3-3 shape, whites 4-2.', 'Team on the ball must play forward to its support player while a middle player makes a third-man run to receive in behind and shoot.', 'Middle players unlimited (or 3) touches, neutrals 2; support players 1 touch; the third-man runner must finish first time.', 'Support player may swap with the shooter.', NULL, '8v8 (+2) + 2 GK', 20, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Position-specific 3-zone third man game', 'phase_of_play', 'opposed', 'in_possession', 47, 47, 'Attacking in and Around the Penalty Area (6 practices): Practice 6', NULL, 'Break into the final zone with combinations including a third-man run; react to losing it.', 'Full width, 3 zones; reds 8 in middle (2-3-3, from GK and 2 CBs behind), whites 8 in middle (4-4); 2 white attackers v 2 red CBs in red''s low zone.', 'Red keeper starts; reds must reach the final zone via a combination with a third man receiving behind the line. Whites can defend the final zone once the ball is there; on winning it they attack the far goal within limited passes or time.', 'Red CBs may not enter middle zone; white attackers only attack; reds may drop back to defend; reds in final zone 2-3 touches or 4-6 seconds; white goals count double. White counter within 6-8 passes or 8-10 seconds.', NULL, NULL, '11v10 approx (8+2+GK v 8+2+GK)', 22, 22, 'Full width, 3 zones', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('One-two and dribble circuit with mannequins', 'passing_unopposed', 'unopposed', 'in_possession', 50, 51, 'Attacking in and Around the Penalty Area (4 practices): Practice 1', NULL, 'One-two combinations and dribbling in attacking combination play.', '40x20 yd area with 8 players, 6 mannequins and 4 cones; 2 players at start and end spots, a ball at each end.', 'Two balls run at once. A: 1 plays 2, who touches past a mannequin; 3 supports and plays a 1-2 with 2, who dribbles to spot 4; mirrored from the other end with a run round the mannequin and a pass into space. B: 1 to 3 to 2, 3 makes a diagonal support run for a 1-2 with 2, then dribble back.', NULL, NULL, 'Quick short passes to feet and space; check away before receiving; weight and timing of the 1-2 into stride; communicate.', '8', 8, 8, '40 x 20 yards', 36.6, 18.3, NULL, false, false, false, NULL, 140),
  ('One-two, third man run and shot', 'combination', 'unopposed', 'in_possession', 52, 52, 'Attacking in and Around the Penalty Area (4 practices): Practice 2', NULL, 'Wide combination play with one-twos, third-man runs and finishing.', '30x30 yd area, goal and keeper, 6 stations with 2 players each (two groups of 3).', 'A: 1 to 2, 2 touches and plays a 1-2 with 3 who has timed his run, then dribbles in and shoots. B: 1 plays a 1-2 with 2 and finds 3; 2 bends his run to shoot off 3''s first-time pass. C: after a 1-2 with 2, 1 passes diagonally to 4 while 3 curves a third-man run to shoot first time.', NULL, 'Three sequences (A, B, C); groups alternate.', NULL, '12 + GK', 13, 13, '30 x 30 yards', 27.4, 27.4, NULL, true, true, true, NULL, 150),
  ('Flank one-two pattern with mannequins', 'combination', 'unopposed', 'in_possession', 53, 54, 'Attacking in and Around the Penalty Area (4 practices): Practice 3', NULL, 'Wide one-twos leading to a shot or cross into the box.', 'Half pitch, 10 players and 12 mannequins; central midfielders start in the centre circle, wide midfielders/forwards and 2 strikers in position, goal and keeper.', 'A: centre player switches wide; wide man touches between mannequins and plays a 1-2 with an attacker who has come across, then dribbles inside to shoot or slip the other attacker running round a mannequin (finish first time). B: after the 1-2 the wide man plays into space for the attacker out wide, who crosses for near-post and far-post runs.', NULL, 'Run both from both sides.', 'Treat mannequins as live defenders; weight and timing of passes; directional touch in front; support angles; well-timed final ball; split near/far post runs.', '10 + GK', 11, 11, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Position-specific 5-zone 11v11 one-two game', 'phase_of_play', 'opposed', 'in_possession', 55, 55, 'Attacking in and Around the Penalty Area (4 practices): Practice 4', NULL, 'Create chances in the final zone through one-twos combined with third-man runs.', 'Full width, halfway line plus 18 yd, 5 zones; reds 8 in 3 middle zones (2-4-2), whites 8 (4-2-1-1), only 2 whites per side zone; red low zone has 2 red CBs v 2 white attackers.', 'Red keeper starts; reds use one-twos plus third-man runs to break in behind, with the support player moving away to open another option. Whites defend the end zone only once the ball enters; on winning it they counter the far goal within limited passes or time.', 'Red CBs may not enter central zone; white attackers attack only; reds may drop to defend; reds in final zone 4-6 seconds to finish; white goals count double; white counter in 6-8 passes or 8-10 seconds.', NULL, NULL, '11v11 (8+2+GK each)', 22, 22, 'Full width x halfway + 18 yards, 5 zones', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('6(+4)v4 centre possession switch game', 'possession', 'overload', 'in_possession', 61, 62, 'Session (Passing in Behind a Defensive Line): Practice 1', 'Spain national team', 'Keep the ball in tight central areas and switch play quickly between grids.', 'Middle of a full pitch split into 2 central grids (full-pitch 5-zone template). 10v10: in one grid 6 whites inside plus 4 whites on the sides against 4 reds; the other 6 reds wait in the other grid.', 'The 6 inside players string 4-6 passes, find an outside support player and get it back to keep going; all three steps scores 1 point. If reds win it they play quickly into the other grid and 4 reds plus all whites shift across to replay the situation there.', 'Variations: inside unlimited/support 2 touches; inside 3 touches/support 1 touch; support player may return to any inside player or only to the passer.', 'Leads into practices 2-5 and the Total Drill where the coach calls practice numbers at random.', NULL, '10v10 (6+4 v 4 in the active grid)', 20, 20, 'central grids of a full pitch', NULL, NULL, NULL, false, false, false, NULL, 180),
  ('10v10 middle zone tactical possession', 'possession', 'opposed', 'in_possession', 63, 63, 'Session (Passing in Behind a Defensive Line): Practice 2', 'Spain national team', 'Possession in the middle third while rehearsing chosen tactical movements by formation.', 'Full width of the pitch, middle zone of the 5-zone template. Reds in a 4-4-2, whites in a 4-3-3; goals not used.', 'One team keeps the ball under pressure using the whole zone while the other presses; on a turnover roles swap. Coach uses it to drill the shapes and movements wanted in possession.', '8-10 passes = 1 point; keep it 30 seconds = 2 points. Back players limited to 2 touches, central midfielders 3, front/wide players unlimited (per formation).', NULL, NULL, '10v10', 20, 20, 'middle third, full width', NULL, NULL, NULL, false, false, false, NULL, 190),
  ('10v10 receive in behind goal zone game', 'positional_game', 'opposed', 'in_possession', 64, 64, 'Session (Passing in Behind a Defensive Line): Practice 3', 'Spain national team', 'Find combinations to get the ball in behind a defensive line and receive it under control.', 'Full pitch: middle zone for play with the two final thirds as end ''Goal Zones''. 10v10 starting in the middle zone.', 'Team in possession combines to slip a pass into the end Goal Zone where a teammate runs on and controls it for 1 point.', 'Defenders cannot enter the Goal Zone until the ball is played in; coach may require 6-8 passes before the final ball or allow it any time.', NULL, NULL, '10v10', 20, 20, 'full pitch, middle zone + 2 end zones', NULL, NULL, NULL, false, false, true, NULL, 200),
  ('10v10 receive in behind and finish', 'small_sided_game', 'opposed', 'in_possession', 65, 65, 'Session (Passing in Behind a Defensive Line): Practice 4', 'Spain national team', 'Same as receiving in behind, now adding a quick finish.', 'As the goal zone game, with 3 goals on each end line: a full-size goal in the middle and a mini goal either side.', 'Player who receives in the Goal Zone goes on to shoot into one of the 3 goals.', 'Middle goal must be a 1-touch finish for 2 points; side mini goals 1 point. Defenders may enter the end zone once the ball is played in.', NULL, 'Right weight, timing, angle and body shape on support and runs in behind; finish quickly with at most 2 touches in the final third.', '10v10', 20, 20, 'full pitch', NULL, NULL, NULL, true, false, true, NULL, 210),
  ('11v11 receive in behind goal zone game', 'conditioned_game', 'opposed', 'in_possession', 66, 66, 'Session (Passing in Behind a Defensive Line): Practice 5', 'Spain national team', 'Apply getting in behind and finishing in a normal game with goalkeepers.', 'Full pitch, full-size goals with keepers; zones kept, play always restarts in the middle zone.', 'Normal 11v11 aiming to score past the keeper after breaking in behind. Then the Total Drill: coach shouts practice numbers 1-5 at random and teams switch straight into that game situation.', 'Unlimited touches in middle zone and 2-3 in the final zone; or unlimited everywhere but must finish within 6-8 seconds once in the final zone.', 'Total Drill linking all 5 practices, called randomly.', NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('9v9 (+2) full back support possession', 'positional_game', 'opposed', 'in_possession', 71, 71, 'Session (Crossing from Deep): Practice 1', 'Spain national team', 'Keep the ball using the full backs out wide in a position-specific set-up.', '45 x 45 yards: 6 middle zones (4 side zones 14 x 8 yds, 2 central 14 x 28 yds) plus 2 end zones 8 x 28 yds with a support goalkeeper each. 8v8: 4v2 in each team''s low central zone (CBs + CMs v 2 strikers), 2v4 in the high central zone, one full back per side zone.', 'Teams move the ball from one support keeper to the other for a point, needing the side players to avoid being outnumbered in the high central zone.', 'CBs, CMs and full backs 2-3 touches, strikers unlimited; nobody leaves their zone.', 'Practice 2 moves it onto a full pitch with wide midfielders.', NULL, '8v8 + 2 support GKs', 18, 18, '45 x 45 yards', 41.0, 41.0, NULL, false, true, true, NULL, 230),
  ('10v10 (+2) full back support, full pitch', 'positional_game', 'opposed', 'in_possession', 72, 72, 'Session (Crossing from Deep): Practice 2', 'Spain national team', 'Same keeper-to-keeper possession with full backs, on a full pitch with 4v4 in midfield.', 'Full pitch with the 6 zones; add right and left wide midfielders for both teams inside the high central zone to make 4v4s. Goals not used, keepers still support players.', 'Same rules and aim as the 9v9 version: work the ball end to end via the full backs.', 'As practice 1.', NULL, 'Quick, quality short passes to feet and into space; open body and receive/pass with the back foot; fast decisions under time and space pressure.', '10v10 + 2 support GKs', 22, 22, 'full pitch', NULL, NULL, NULL, false, true, true, NULL, 240),
  ('Crossing from deep zonal game', 'small_sided_game', 'opposed', 'in_possession', 73, 73, 'Session (Crossing from Deep): Practice 3', 'Spain national team', 'Use the full backs to deliver early crosses into the box.', 'Same 6-zone full-pitch layout with 2 full-size goals and keepers; full backs alone in the side zones, 4v4s centrally.', 'Teams work it wide to the full back who crosses from deep; all players from the high central zone may break into the box to attack the cross.', NULL, NULL, NULL, '10v10 + 2 GKs', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 250),
  ('11v11 crossing zonal game, double goals', 'conditioned_game', 'opposed', 'in_possession', 74, 74, 'Session (Crossing from Deep): Practice 4', 'Spain national team', 'Finish the session in a normal game rewarding goals from wide crosses.', 'Full pitch with side zones marked; reds 4-4-2 v whites 4-3-3.', 'Normal 11v11.', 'Goal = 1; goal scored directly from a cross out of a side zone counts double.', NULL, NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Continuous 5v5 crossing and finishing', 'finishing', 'opposed', 'in_possession', 78, 78, 'Session (Crossing from the Byline): Practice 1', 'Spain national team', 'Crossing, heading, attacking and defending crosses and movement in the box.', 'Area twice the size of the penalty box with 2 full-size goals and keepers; two teams of 5 inside and 4 neutral crossers on the sides, each with balls (2 serve to each goal).', 'One side attacks: a neutral crosses from the right for a 5v5 in front of goal; when it ends the next neutral crosses from the left into the same end. Then everyone turns to the other goal, roles swap and the other two neutrals serve.', NULL, 'Practice 2 adds quick wide transitions.', NULL, '5v5 + 2 GKs + 4 neutrals', 16, 16, 'double penalty area', NULL, NULL, NULL, true, true, true, NULL, 270),
  ('Crossing with quick wide counter attacks', 'finishing', 'opposed', 'to_attack', 79, 79, 'Session (Crossing from the Byline): Practice 2', 'Spain national team', 'Crossing and finishing plus fast transition to attack out wide.', 'Half a pitch with zones: 4v4 in each of two central zones, 4 neutrals in the side zones, a goal and keeper at each end. Players stay in their zone and may only shoot at their goal.', 'Team in possession moves it quickly to the other zone and to a neutral who crosses for a 4v4 attack. Defenders who clear it transition at once the same way (pass to other zone, neutral crosses).', 'Goal = 1 point; players stay in zones.', NULL, 'Coordinate runs (near post, far post, one arriving late); finish in 1 touch; cross accuracy, weight and timing.', '8v8 + 4 neutrals + 2 GKs', 22, 22, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 280),
  ('2v1 flank play dynamic zonal game', 'conditioned_game', 'opposed', 'in_possession', 80, 80, 'Session (Crossing from the Byline): Practice 3', 'Spain national team', 'Create 2v1s on the flanks and cross from near the byline.', 'Full pitch with a full-size goal placed 18 yds past halfway; the zone between box and halfway split into 3 (2 side zones). Reds 4-3-3 v whites 4-4-2 diamond; only full backs and the red wide forwards may enter side zones.', 'Reds use the side zones to get 2v1 and cross from the byline. Whites who win it must finish a counter within 10 seconds. Every restart is from the red keeper; swap roles after a set time.', 'Red goal through the centre = 1, after a cross from a side zone = 2; white counters within 10 s.', NULL, NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Target man knock-down shot, unopposed', 'combination', 'unopposed', 'in_possession', 82, 82, 'Session (Creating Space to Shoot from Outside the Box, 1): Practice 1', 'Spain national team', 'Combination play, striker hold-up as a target man and shooting from distance.', 'Half pitch, 4 players (2 CMs, 1 attacking mid, 1 striker from a 4-2-3-1) plus GK; cones for the attacking mid and striker positions.', 'GK plays long to a CM, who passes to the attacking mid, who sets the other CM. That CM chips into the striker while the AM and first CM run up either side; striker heads down to one of them who controls and shoots.', NULL, 'Practice 2 adds 2 centre backs.', NULL, '4 + GK', 5, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 300),
  ('Target man knock-down shot v 2 defenders', 'combination', 'opposed', 'in_possession', 83, 83, 'Session (Creating Space to Shoot from Outside the Box, 1): Practice 2', 'Spain national team', 'Same pattern under pressure from 2 defenders.', 'As practice 1 with 2 centre backs behind the striker (3v2 + GK).', 'One defender contests the striker in the air (1v1); the second presses the midfielder coming to shoot but only inside the penalty area.', 'Second defender may not leave the box.', NULL, 'Chip pass accuracy and height so the striker wins the header; supporters arrive fast but time their stride; shoot before the defender closes the angle.', '3v2 + GK (plus GK server)', 6, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Target man 7v6 three zone game', 'small_sided_game', 'opposed', 'in_possession', 84, 84, 'Session (Creating Space to Shoot from Outside the Box, 1): Practice 3', 'Spain national team', 'Target-man hold-up and long shots within a small-sided game.', 'Second full-size goal 10-12 yds from halfway, 3 zones: zone 1 3v2 (2 CMs + AM v 2 opposing CMs), zone 2 2 attacking mids + striker, final zone (box) 3 opposing centre backs. Keepers both ends.', 'From the red GK, reds work a 3v2 then chip to the striker on the box edge; 1-2 players push up to support. Whites who win it attack the other goal 2v3.', 'White goals count double. The 3 CBs defend actively but stay in the box. One middle-zone AM supports the striker, the other joins if a CM does not.', NULL, NULL, '7v6 + GKs', 15, NULL, 'half pitch plus', NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Target man 9v10 zonal game', 'conditioned_game', 'opposed', 'in_possession', 85, 85, 'Session (Creating Space to Shoot from Outside the Box, 1): Practice 4', 'Spain national team', 'Chipped pass into the striker and supported finish across the full width.', 'Full pitch width; reds in a 2-2-3-1 (4-2-3-1 minus CBs), whites in a 5-4-1. Always starts with the red keeper (8v10 outfield).', 'Reds chip from the low zone over/through the white midfield line to the striker and at least 2 players run forward to support, then find a way to finish (3 example routes to goal).', NULL, NULL, NULL, '9v10 (incl. GKs)', 19, NULL, 'full pitch width', NULL, NULL, NULL, true, true, true, NULL, 330),
  ('4 zone 6v6 central shooting game', 'small_sided_game', 'opposed', 'in_possession', 89, 89, 'Session (Creating Space to Shoot from Outside the Box, 2): Practice 1', 'Spain national team', 'Quick forward passing through the midfield line and shooting.', '40 x 30 yds split into 4 zones of 10 x 30, full goals and keepers at each end, 3 players of a team per zone (6v6 outfield), all locked in zones.', 'Pass forward through the opponents'' first line of 3 and shoot past the final 3, who try to block from their zone.', 'Unlimited or 2-3 touches.', 'Practice 2 lets a defender drop back in.', NULL, '6v6 + 2 GKs', 14, 14, '40 x 30 yards', 37.0, 27.0, NULL, true, true, true, NULL, 340),
  ('4 zone shooting game with recovering defender', 'small_sided_game', 'opposed', 'in_possession', 90, 90, 'Session (Creating Space to Shoot from Outside the Box, 2): Practice 2', 'Spain national team', 'Shoot quickly once through the line before a recovering defender arrives.', 'As the 4 zone game.', 'When the ball goes from low to high zone, one of the 3 bypassed defenders may leave his zone and press from behind, making it 3v3(+1).', 'One bypassed defender may chase back.', NULL, 'Directional first touch to get a shot off quickly; use 1-touch combinations to shift defenders and open gaps.', '6v6 + 2 GKs', 14, 14, '40 x 30 yards', 37.0, 27.0, NULL, true, true, true, NULL, 350),
  ('6v6 shoot from distance v 3 mini goals', 'small_sided_game', 'opposed', 'in_possession', 91, 91, 'Session (Creating Space to Shoot from Outside the Box, 2): Practice 3', 'Spain national team', 'Pass through the midfield line and shoot from distance under pressure.', 'Area around the box: full goal with keeper at one end, 3 mini goals on the halfway line. Reds 4-2 (or 3-3), whites 2-2-2 with 2 CBs restricted to the box height line.', 'Reds (6v4 in the main area) try to finish from outside the box. Whites win it and score in the mini goals; reds must defend quickly on losing it.', 'Red goal from outside the box = 2; white mini goal = 1. White CBs may join counters but stay in their zone.', NULL, NULL, '6v6 + GK', 13, 13, 'penalty box to halfway', NULL, NULL, NULL, true, true, true, NULL, 360),
  ('Dribble inside past mannequins and shoot', 'technical', 'unopposed', 'in_possession', 93, 93, 'Session (Dribbling & Creativity): Practice 1', 'Spain national team', 'Dribble inside from the flank to beat players and make space to shoot.', 'Two groups wide left and right of the box; 3 mannequins in each corner of the penalty area; GK in goal.', 'Each player weaves through the 3 mannequins with close control and shoots after the last one. Start slowly and build to full speed.', NULL, NULL, 'Soft, quick touches at speed; check the keeper''s position and pick the corner.', '2 groups + GK', NULL, NULL, 'penalty area', NULL, NULL, NULL, true, true, true, NULL, 370),
  ('Continuous 1v1 duels with switch of play', 'one_v_one', 'opposed', 'in_possession', 94, 95, 'Session (Dribbling & Creativity): Practice 2', 'Spain national team', 'Dribbling, 1v1 play, combination play and switching play.', 'Equal groups either side of the box (8+ players), positions A-D on each side, GK in goal.', 'Part 1: a left player steps across to defend; right attacker A goes 1v1 and shoots. Meanwhile right players C and B play a one-two and C switches long to the left. Part 2: the left player receives and dribbles in while the previous attacker crosses over to defend; the left side then one-twos and switches back. Players always cross to defend after shooting then rejoin at position D on the other side.', NULL, NULL, NULL, '8+ plus GK', 9, NULL, 'around the penalty area', NULL, NULL, NULL, true, true, true, NULL, 380),
  ('Double 1v1 flank to box finishing', 'one_v_one', 'opposed', 'in_possession', 96, 96, 'Session (Dribbling & Creativity): Practice 3', 'Spain national team', 'Dribbling, 1v1 play and shooting in the box.', 'Two side zones on the flanks, each with a defender and a mini goal behind; a second defender inside the box; GK in goal.', 'Attacker takes on the first defender in the side zone; if he beats him and crosses the line he faces a second 1v1 in the box and shoots. If the defender wins it he counters into the mini goal. Attackers switch sides after shooting.', 'Defender winning the ball scores in the mini goal.', NULL, 'Be creative with feints; shield with the body between man and ball; shoot as soon as you enter the box.', 'attackers + 2 defenders per side + GK', NULL, NULL, 'flank to penalty area', NULL, NULL, NULL, true, true, true, NULL, 390),
  ('Switching positions combination pattern', 'passing_unopposed', 'unopposed', 'in_possession', 101, 101, 'Session (Switching Positions to Create Space): Practice 1', 'Spain national team', 'Pass weight and movement timing for an in-and-out positional switch combination.', '28 x 14 yds split into 2 grids; 8 players, 4 on the sides and 4 inside, forming 2 diamonds.', 'Repeat the analysed Cazorla/Fabregas move: while the 4th pass travels the side player curls inside in front of the next player and receives, then that player swaps out to take the side spot. Shape is kept throughout.', '2 touches.', 'Practices 2-5 add opposition and goals.', NULL, '8', 8, NULL, '28 x 14 yards', 26.0, 13.0, NULL, false, false, false, NULL, 400),
  ('6v6 (+4) switching positions possession', 'possession', 'overload', 'in_possession', 102, 102, 'Session (Switching Positions to Create Space): Practice 2', 'Spain national team', 'Use the switching combination while keeping the ball against 6.', 'Same grid; 2 teams of 6 plus 4 neutrals (one each end, 2 inside). Possession team has 4 inside and 2 on the sides; other team all 6 inside.', 'Keep possession; 6-8 passes = 1 point, doing it with the switching combination = 2. A side and neutral can combine but another inside player must refill the side spot. On a turnover 2 whites go to the sides.', 'Variations: team unlimited/neutrals 2 touches; 3 and 2; 2 and 1.', NULL, NULL, '6v6 + 4 neutrals', 16, 16, '28 x 14 yards', 26.0, 13.0, NULL, false, false, false, NULL, 410),
  ('7v7 (+4) switching positions and finishing', 'small_sided_game', 'overload', 'in_possession', 103, 103, 'Session (Switching Positions to Create Space): Practice 3', 'Spain national team', 'Same combination in a small-sided game with a finish.', 'Full pitch, central zone marked for the same 16 players; GKs in both goals.', 'Complete 6-8 passes with the combination in the zone, then break out and score past the keeper.', 'Defenders stay in the zone; attacker has limited touches or time to finish (2-3 touches or 4-6 s). Option: 2 attackers + 1 defender may leave, attackers 2 touches outside and 1-touch finish. Then all may leave once it is played out.', NULL, NULL, '7v7 + 4 neutrals + GKs', 18, NULL, 'central zone of full pitch', NULL, NULL, NULL, true, true, true, NULL, 420),
  ('9v9 switching positions finishing game', 'small_sided_game', 'opposed', 'in_possession', 104, 104, 'Session (Switching Positions to Create Space): Practice 4', 'Spain national team', 'Switching-positions combination then attack the goal.', 'Full pitch, bigger central zone 55 x 50 yds; no neutrals; 8v8 inside with 2 white CBs on the zone line; both sides 2-3-3, no full backs.', 'Complete 6-8 passes with the combination, then leave the zone to score.', 'CBs cannot follow out of the zone, attackers 2-3 touches before shooting; or CBs may defend outside once the ball is played out.', NULL, 'Use the inside/outside swap; 1 touch where possible.', '9v9 incl. GKs', 18, 18, '55 x 50 yards zone', 50.0, 46.0, NULL, true, true, true, NULL, 430),
  ('11v10 switching positions position game', 'conditioned_game', 'overload', 'in_possession', 105, 105, 'Session (Switching Positions to Create Space): Practice 5', 'Spain national team', 'Apply the combination in a position-specific full-pitch game.', 'Full pitch with central zone; reds 4-1-3-2, whites 3-4-2 (add red full backs and a third white CB).', 'Reds combine for 6-8 passes then leave the zone to attack; whites win it and counter. Always restarts with reds.', '3 white CBs cannot follow out, attackers 2-3 touches before shooting; or CBs may defend outside once it is played out.', NULL, 'Opposite movements (one in, one out); mix passes to feet and into space; whites keep compact central organisation.', '11v10', 21, 21, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 440),
  ('Two triangle switch of play pattern', 'passing_unopposed', 'unopposed', 'in_possession', 109, 109, 'Session (Maintaining Possession then Switching to Weak Side): Practice 1', 'Spain national team', 'Attacking combination with a change of direction (switching play).', '2 triangles 30-40 yds apart, 7+ players.', 'In one triangle 2 passes to 1, 1 to 3, 3 back to 2 who has come to support; 2 hits a long switch to the far triangle where the same sequence repeats and returns. Players rotate to the next position; run it both directions.', '1 touch.', 'Practice 2 uses 4 positions per side.', 'Rhythm with passes timed to movement; angles and distances of support; accurate weighted passes to feet; talk and visual cues.', '7+', 7, NULL, '30-40 yards between triangles', 32.0, NULL, NULL, false, false, false, NULL, 450),
  ('Four position switch of play pattern', 'passing_unopposed', 'unopposed', 'in_possession', 110, 110, 'Session (Maintaining Possession then Switching to Weak Side): Practice 2', 'Spain national team', 'Longer short-pass sequence before a long switch.', '4 positions on each side of the area, 9+ players.', '2 to 1, 1 to 4, 4 to 3, 3 switches long to 6; 6 to 5, 5 to 8, 8 back to 7 who supports, 7 switches back to 2. Rotate positions; run both ways.', '1 touch.', NULL, 'Open body shape, receive and pass with the back foot; 1 touch.', '9+', 9, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 460),
  ('Build from back one-two pattern to shot', 'combination', 'unopposed', 'in_possession', 111, 111, 'Session (Maintaining Possession then Switching to Weak Side): Practice 3', 'Spain national team', 'Possession pattern of short passes and one-twos ending in a shot.', 'Full pitch, 8 outfield players in set positions (1, 2a/2b, 3, 4/4b, 5, 6, 7) plus GK.', '1 and 2a exchange, 1 finds 3, 3 sets 2a who returns into 3''s path. 3 dribbles on, one-twos with 4 and 5, passes to 6, 6 to 7, and 3 makes a third-man run to get 7''s pass in the box and shoot. Repeat using 2b and 4b.', NULL, NULL, '1 touch where possible.', '8 + GK', 9, NULL, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 470),
  ('Weak side switch position combination', 'combination', 'passive', 'in_possession', 112, 113, 'Session (Maintaining Possession then Switching to Weak Side): Practice 4', 'Spain national team', 'Short passing in midfield, switch play and finish fast on the weak side.', 'Half-plus pitch, players in a 4-3-3 / 4-1-4-1 positions; mannequins as the back line; GK in goal.', 'Midfielders 6, 8, 10 combine, 8 switches long to the right back, who returns to the CB; CB hits the striker who sets the right forward. Option A: early ball in behind the mannequins to the far-side forward (11). Option B: pass into the advanced right back''s run, then cross with 9 near post, 11 far post, 10 arriving late.', NULL, NULL, 'Coach chooses who attacks near/far post; favour option A as it is quicker and hits defenders facing their own goal; option B gives defenders time so exploit the weak side fast.', '10 + GK', 11, NULL, 'half pitch plus', NULL, NULL, NULL, true, true, true, NULL, 480),
  ('Weak-side switch 4-zone full-pitch game', 'phase_of_play', 'overload', 'in_possession', 114, 114, 'Switching Play to the Weak Side: Practice 5', 'Spain national team', 'Overload one side with combination play, then switch and attack the weak side quickly using two rehearsed solutions.', 'Full pitch with a middle zone split into left and right grids; reds 4-3-3/4-1-4-1 v whites 4-4-2/4-2-3-1, keepers in both goals; reds have a 6v5 in the ball grid, other players wait in the other grid.', 'Reds build from their keeper, combine in one grid, and either switch and cross early to the far forward or release the overlapping full back; if they move the ball across they recreate the 6v5 there. Whites who win it must finish within 10 seconds.', '6 passes in a grid before attacking from it (6 more after a switch); whites defend only their own grid; reds 2-3 touches then 1-2; whites unlimited.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 490),
  ('10v10 six-zone pass-through-lines game', 'possession', 'opposed', 'in_possession', 119, 119, 'Passing through the Midfield Line in the Centre: Practice 1', 'Spain national team', 'Quick combinations aimed at passing forward through successive lines.', '36 x 20 yd area cut into six 6 x 20 yd strips; each team of 10 holds three alternating strips (2 at the back end, 4 and 4 in the others); everyone stays in their strip except the 2 safe-zone players who may step forward.', 'Team starting in its end zone tries to play forward through its three zones and back again; on a turnover the other team has the same aim.', '2-3 touches (1-2 after winning it); 1 point per pass between zones; 2 bonus points for going all three zones and back.', NULL, NULL, '10v10', 20, 20, '36 x 20 yards', 32.9, 18.3, NULL, false, false, true, NULL, 500),
  ('3-zone possession game with central safe zone', 'positional_game', 'overload', 'in_possession', 120, 120, 'Passing through the Midfield Line in the Centre: Practice 2', 'Spain national team', 'Play into a free central zone so a midfielder can receive, turn and feed the far grid.', '65 x 45 yd area: two 30 x 45 yd end zones and a 5 x 45 yd middle safe zone; 10v10; 7v6 in the starting zone and 3v4 in the far one; reds 4-3, whites 4-2.', 'Reds pass into the safe zone where a midfielder runs in unmarked, then play into the far grid as three reds and two whites shift across to recreate the 7v6. Roles swap when whites win it.', 'Unlimited or 3 touches; safe-zone receiver may be limited to 2 touches.', NULL, 'Shift zones fast to give options; weight and time the pass into the safe zone for the run forward.', '10v10', 20, 20, '65 x 45 yards', 59.4, 41.1, NULL, false, false, true, NULL, 510),
  ('Midfield-line break zonal game to goal', 'phase_of_play', 'overload', 'in_possession', 121, 121, 'Passing through the Midfield Line in the Centre: Practice 3', 'Spain national team', 'Rehearse the Xavi-v-Russia pattern: receive behind the midfield line then release the attack in the final third.', 'Full pitch in six zones (high zone split into centre, two side channels and a safe zone); 7v7 in the middle zone, reds 4-3-3 v whites 4-2 or 4-1-1; 3v4 in the high zone; keepers in both goals.', 'Reds pass into the safe zone behind the midfield line, the receiver has 2 touches to feed the high zone and runs on to support; forward options are a ball in behind for a runner or a ball wide to the full back in the side channel. Whites who win it may go anywhere and counter.', 'Low-zone reds unlimited, safe-zone player 2 touches, high-zone touches set by coach; red defenders may not drop into the low zone until the ball does.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 520),
  ('Midfield-line break 5-zone game v 2-3-1', 'phase_of_play', 'overload', 'in_possession', 122, 122, 'Passing through the Midfield Line in the Centre: Practice 4', 'Spain national team', 'Rehearse the Torres-v-Germany pattern: midfielder receives in a safe strip and plays in behind for a runner.', 'Full pitch split into five vertical zones with a low safe strip for the reds; 7v6 in the zone ahead of it (reds 4-3, whites 2-3-1); 3 attackers v 2 centre backs in the high zone; keepers.', 'Reds feed a midfielder in the safe strip; he has 2 touches to play one of three balls in behind (wide either side of the centre backs or between them for the striker) and then joins the attack. Whites who win it may counter anywhere.', 'Safe-strip receiver 2 touches; defenders fully active after the pass.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 530),
  ('Midfield-line break 5-zone game, 4v4 up top', 'phase_of_play', 'opposed', 'in_possession', 123, 123, 'Passing through the Midfield Line in the Centre: Practice 5', 'Spain national team', 'Same Torres-goal pattern but finishing against a full back line.', 'As the previous 5-zone game but whites add both full backs, giving a 4v4 in the high zone.', 'Reds get into the safe strip behind the midfield line and attack the 4v4 quickly; whites counter on a turnover.', 'Same rules as the previous practice.', NULL, 'Can be adapted to any formation; safe zone gets players used to receiving behind the midfield line; finish the 4v4 fast.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 540),
  ('6v6 (+6) five-zone possession with neutrals', 'possession', 'overload', 'in_possession', 126, 126, 'Passing through the Midfield Line on the Flank: Practice 1', 'Spain national team', 'Quick combinations, moving the ball wide and keeping it.', '45 x 35 yd area: 35 x 25 central zone, two 35 x 5 side zones, two 5 x 35 end zones; 6v6 inside (both 2-3-1); one neutral in each side zone (full backs) and two in each end zone (centre backs).', 'Keep the ball using the neutrals to work it end to end; roles swap on a turnover.', '8 passes = 1 point, 30 seconds of possession = 2; neutral-to-neutral passes do not count and max 2 in a row; touch limits progress from free/1-2 for neutrals down to 1 touch for all.', NULL, NULL, '6v6+6', 18, 18, '45 x 35 yards', 41.1, 32.0, NULL, false, false, false, NULL, 550),
  ('10v10 five-zone positional possession', 'possession', 'opposed', 'in_possession', 127, 127, 'Passing through the Midfield Line on the Flank: Practice 2', 'Spain national team', 'Keep possession under pressure using real full backs and centre backs on the outside.', 'Same 45 x 35 yd five-zone area; neutrals replaced by each team''s own full backs and centre backs in the outer zones.', 'Same objectives and scoring as the neutral version, now much harder as outside players belong to a team.', 'Neutral rules from the previous game apply to the outside players.', NULL, 'Open body, receive on back foot; mix feet and space passes; support angles and distances; quick decisions; press as a unit.', '10v10', 20, 20, '45 x 35 yards', 41.1, 32.0, NULL, false, false, false, NULL, 560),
  ('11v11 flank attack through 3-zone midfield', 'conditioned_game', 'opposed', 'in_possession', 128, 129, 'Passing through the Midfield Line on the Flank: Practice 3', 'Spain national team', 'Keep it in the centre then release an advanced full back on the flank to get behind the lines.', 'Full pitch with a middle attacking zone split into a central and two side zones; reds 4-2-3-1 v whites 4-1-4-1; only full backs may enter the side zones (a wide forward may for a one-two).', 'Reds circulate in the centre and pick the moment: (A) ball out to the full back who crosses, or (B) wide forward feeds the full back then cuts diagonally inside for a return down the line and crosses. Whites who win it must finish within 10-12 seconds.', 'Goal through the centre 1 point, from the flank 2; whites 2 points if they score within 10-12 seconds.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 570),
  ('8v8 (+4) two-zone pass-in-behind game', 'positional_game', 'overload', 'in_possession', 133, 133, 'Attacking in Behind the Defensive Line: Practice 1', 'Spain national team', 'Possession with the end product of a pass behind the defensive line.', '60 x 40 yd area in two 30 x 40 yd zones; two teams of 8 (2-3-3) plus 2 neutrals in each zone.', 'After 6-8 passes the team plays into the other zone for a teammate running in behind; everyone but the neutrals moves across and repeats. Count restarts at once or only after the whole team has crossed.', 'Each successful switch = 1 point; roles swap on a turnover; unlimited/3 touches with neutrals 2, then 2 touches with neutrals 1.', NULL, NULL, '8v8+4', 20, 20, '60 x 40 yards', 54.8, 36.6, NULL, false, false, true, NULL, 580),
  ('8v8 two-zone game to four mini goals', 'small_sided_game', 'opposed', 'in_possession', 134, 134, 'Attacking in Behind the Defensive Line: Practice 2', 'Spain national team', 'Pass behind the defensive line and finish accurately.', 'Same 60 x 40 two-zone area, neutrals removed, two mini goals on each end line.', 'Attacking team plays past the defenders into the far zone for a runner and scores in one of that zone''s mini goals. Defenders who win it counter within 6-8 seconds; play restarts from the other zone with the other team.', 'Counter must finish in 6-8 seconds.', NULL, NULL, '8v8', 16, 16, '60 x 40 yards', 54.8, 36.6, NULL, true, false, true, NULL, 590),
  ('8v8 two-zone game to full goals', 'small_sided_game', 'opposed', 'in_possession', 135, 135, 'Attacking in Behind the Defensive Line: Practice 3', 'Spain national team', 'Pass in behind and finish against a keeper.', 'Same two-zone area with two full-size goals and keepers instead of mini goals.', 'As the mini-goal version: break the line into the far zone and shoot.', NULL, NULL, 'Vary short and long passes; weight and time the final ball for the run; one touch where possible; one-touch finishes; quick support runs into the high zone.', '8v8+2 GK', 18, 18, '60 x 40 yards', 54.8, 36.6, NULL, true, true, true, NULL, 600),
  ('9v9 (+2) three-zone game, full pitch', 'phase_of_play', 'overload', 'in_possession', 136, 136, 'Attacking in Behind the Defensive Line: Practice 4', 'Spain national team', 'Possession leading to a pass in behind, crossing and finishing.', 'Full pitch with a middle zone; 8v8 plus 2 neutrals inside it, keepers in both goals; team in possession 2-3-3 or 3-2-3, building from its keeper.', 'Both neutrals must touch the ball before attackers may leave the zone to finish in the final third; defenders may leave once an attacker does. Roles swap on a turnover with the same conditions.', 'Both neutrals touch before attacking.', NULL, NULL, '9v9+2', 20, 20, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 610),
  ('11v11 three-zone in-behind game', 'conditioned_game', 'opposed', 'in_possession', 137, 137, 'Attacking in Behind the Defensive Line: Practice 5', 'Spain national team', 'Full-team version of attacking in behind the defensive line.', 'Full pitch, same three zones; neutrals removed; reds 4-3-3 v whites 4-2-3-1.', 'Play as the 9v9 game with full teams: circulate in the middle zone and release runners in behind.', NULL, NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 620),
  ('6v4 possession and press transition', 'transition', 'overload', 'to_defend', 142, 142, 'Building Up Play Against a High Press (1): Practice 1', 'Spain national team', 'Keep the ball and press immediately when it is lost.', '18 x 12 yd grid, 10 players: reds have 4 on the sides (centre backs/attackers top and bottom, full backs on the sides) and 2 central midfielders inside; 4 whites inside.', 'Reds open up and keep the ball; on losing it all six rush in to win it back while whites try to keep it.', 'Reds 2 touches, whites unlimited; reds 8-10 passes = 1 point, 30 seconds = 2; whites 4-5 passes or 6 seconds = 1.', NULL, 'Open when you have it, close in around the ball when you lose it.', '6v4', 10, 10, '18 x 12 yards', 16.5, 11.0, NULL, false, false, false, NULL, 630),
  ('4 (+2) v 4 role-swap possession', 'rondo', 'overload', 'to_defend', 143, 143, 'Building Up Play Against a High Press (1): Practice 2 (variation)', 'Spain national team', 'React to the change of possession in both directions.', 'Same 18 x 12 yd grid; two teams of 4 plus 2 neutrals inside who join the team with the ball; team in possession on the sides, the other inside.', 'Keep the ball; when the defenders win it the teams swap places at once, the new attackers going to the sides.', 'All 2 touches, neutrals 1.', NULL, 'Support angles and communication; accurate short passes; open body shape; react fast to the switch.', '4v4+2', 10, 10, '18 x 12 yards', 16.5, 11.0, NULL, false, false, false, NULL, 640),
  ('Two-grid build-up and support possession', 'positional_game', 'overload', 'in_possession', 144, 144, 'Building Up Play Against a High Press (1): Practice 3', 'Spain national team', 'Move the ball forward from the back quickly and support it.', 'Two 18 x 12 yd grids, 12 players: teams of 4 plus 4 neutrals; start grid has 3 reds on the sides, 1 inside, neutrals at the bottom and inside (6v4); the other two neutrals wait in the far grid.', 'After 6-8 passes play to the other grid and everyone but the 2 neutrals shifts across to go again. Defenders who win it either keep it in that grid first or switch straight away.', '2 touches; neutrals 1.', NULL, NULL, '4v4+4', 12, 12, 'Two 18 x 12 yard grids', 16.5, 11.0, NULL, false, false, true, NULL, 650),
  ('6v5 build-out under pressure to fast attack', 'phase_of_play', 'overload', 'in_possession', 145, 145, 'Building Up Play Against a High Press (1): Practice 4', 'Spain national team', 'Keep the ball in the defensive zone then break out with a fast attack.', 'Full pitch; square zone with 6v4 inside plus one extra white defender between halfway and a line 8 yards beyond it; full goals with keepers.', 'Red keeper plays into the square; after 8 passes reds launch a 5-player attack with a pass to a runner in behind and finish (one red stays back). Whites who win it in the square attack the other goal; reds must win it back and recycle 8 passes.', 'Touch limits vary (2-3 all; outside 1 and inside 2-3, or reverse); free touches in the high zone; whites 6 seconds to finish; back white passive or active.', NULL, NULL, '6v5 + 2 GK', 13, 13, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 660),
  ('Dynamic two-zone build-up and fast attack', 'phase_of_play', 'overload', 'in_possession', 146, 146, 'Building Up Play Against a High Press (1): Practice 5', 'Spain national team', 'Keep the ball in one wide build-up zone then attack fast 4v3.', 'Full pitch, a 24 x 24 yd zone on each side plus a 6 x 24 yd zone between, and a line 12 yards past halfway; 10v10 plus keepers; 3 red outside and 3 white inside per zone, one red and one white between, a lone red attacker v 3 white defenders up front.', 'Red keeper plays into a zone; after 8 passes reds go 4v3 (2 from the zone, the top player and the attacker). Whites who win it attack the opposite goal (double goals); reds who win it back reset.', 'Earlier touch limits may apply.', NULL, 'Open with the ball, close when it is lost.', '10v10 + 2 GK', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 670),
  ('7v4 possession and press transition', 'transition', 'overload', 'to_defend', 149, 149, 'Building Up Play Against a High Press (2): Practice 1', 'Spain national team', 'Keep the ball and press immediately when it is lost.', '18 x 12 yd grid, 11 players: reds 4 on the sides plus 3 central midfielders inside, 4 whites inside.', 'Reds keep possession; when they lose it they close down at once to win it back.', 'Outside reds 2 touches, inside reds 1, whites unlimited; reds 8-10 passes = 1 point, 30 seconds = 2; whites 4-5 passes or 6 seconds = 1.', NULL, 'Open with the ball, close without it.', '7v4', 11, 11, '18 x 12 yards', 16.5, 11.0, NULL, false, false, false, NULL, 680),
  ('4 (+3) v 4 role-swap possession', 'rondo', 'overload', 'to_defend', 150, 150, 'Building Up Play Against a High Press (2): Practice 2', 'Spain national team', 'Fast transitions both ways in tight space.', '18 x 12 yd grid; teams of 4 plus 3 neutrals inside with the ball side; team in possession on the sides.', 'Keep it; when the inside team wins it they take the outside spots and the losers move in and press.', '2 touches; then 2 with neutrals 1; then 1 touch.', NULL, 'Support angles and distances; timing and weight of passes; quick reactions to the change.', '4v4+3', 11, 11, '18 x 12 yards', 16.5, 11.0, NULL, false, false, false, NULL, 690),
  ('Two-grid build-up possession (2)', 'positional_game', 'overload', 'in_possession', 151, 151, 'Building Up Play Against a High Press (2): Practice 3', 'Spain national team', 'Build from the back and support quickly, 4 (+3) v 4.', 'Two 18 x 12 yd grids; teams of 4 plus 4 neutrals; one player from the team with the ball must stay on the halfway line, the rest inside; 1 neutral at the far end.', 'After 6-8 passes switch grid; everyone except the end neutral moves across and a new player takes the halfway spot. Defenders who win it keep it first or switch straight away.', '2 touches (or 1); or 2 with neutrals 1.', NULL, NULL, '4v4+4', 12, 12, 'Two 18 x 12 yard grids', 16.5, 11.0, NULL, false, false, true, NULL, 700),
  ('Continuous four-grid possession and press', 'possession', 'overload', 'in_possession', 152, 152, 'Building Up Play Against a High Press (2): Practice 4', 'Spain national team', 'Short passing in a 4 (+3) v 4 and switching the point of attack across grids.', 'Four 12 x 12 yd grids, 22 players: 15 reds and 7 whites; one grid has 3 reds inside, 4 outside and 4 whites; each other grid holds one white.', 'After 6-8 passes play into another grid; 2 inside reds and 3 whites shift across and the outside red on the shared line steps in. Whites who win it try to keep it while the 7 reds counter-press for 6 seconds.', 'Whites 1 point for 6 seconds or 4-5 passes; reds 2 touches then 1.', NULL, NULL, '15 v 7', 22, 22, 'Four 12 x 12 yard grids', 21.9, 21.9, NULL, false, false, false, NULL, 710),
  ('11v11 low-zone possession, switch and fast attack', 'conditioned_game', 'overload', 'in_possession', 153, 153, 'Building Up Play Against a High Press (2): Practice 5', 'Spain national team', 'Keep it in your own third, switch play and launch a fast attack.', 'Full pitch split by a line box to box, with two grids between box and halfway; reds 4-4-2 (bowl), whites 4-2-3-1/4-4-2; 7v4 in the left grid plus 3 white outside, 3 (+1) v 2 (+1) in the right.', 'Reds build from the keeper, make 6-8 passes in one grid, then either switch and break, or rebuild 7v4 in the other grid, switch back and break. Whites who win it attack (goals double); reds close in fast and reset on regaining.', 'Goals by whites count double.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 720),
  ('Diagonal runs and combination dribble pattern', 'combination', 'passive', 'to_attack', 159, 159, 'Quick Transition to Attack when Defending a Corner Kick: Practice 1', 'Spain national team', 'Diagonal runs behind defenders, combinations and running with the ball at speed.', '18 x 8 yd lane with 2 cones and 6 mannequins, 2 players; part B uses 2 small cones, 4 large cones and 4 mannequins.', 'A: player 1 passes to 2 and cuts diagonally behind a mannequin; 2 takes a directional touch, returns the ball and cuts the other way, repeating up the lane. B: after the second cut player 1 dribbles into a cone goal while 2 recovers to stop him.', NULL, 'Part B adds the finish through a cone goal under pressure.', 'Fast-break pace; pass in front of the runner timed to his run; communicate to avoid collisions.', '2 players', 2, 2, '18 x 8 yards', 16.5, 7.3, NULL, false, false, true, NULL, 730),
  ('Third-man runs and dribble pattern', 'combination', 'passive', 'to_attack', 160, 160, 'Quick Transition to Attack when Defending a Corner Kick: Practice 2', 'Spain national team', 'Add a third-man run to the diagonal cutting and dribbling pattern.', 'Same lane, 3 players, 2 cones and 6 mannequins (B: 2 small cones, 4 large cones, 4 mannequins).', 'A: A passes diagonally to B while C cuts across a mannequin to support; B finds C, C dribbles round the next mannequin and passes to A as B cuts the other way. B: after the second cut B dribbles into the cone goal with A chasing.', 'Rotate positions; run from both sides.', 'Part B adds a pressured finish through a cone goal.', NULL, '3 players', 3, 3, '18 x 8 yards', 16.5, 7.3, NULL, false, false, true, NULL, 740),
  ('Corner clearance to fast break, opposite flank', 'transition', 'passive', 'to_attack', 161, 162, 'Quick Transition to Attack when Defending a Corner Kick: Practice 3', 'Spain national team', 'Defend a corner then launch a quick counter down the opposite flank.', 'Three-quarters of a pitch with an extra goal and 5 mannequins; 9 players start in corner-defending spots; coaches with balls on both sides.', 'A cross is caught by the keeper who rolls it to a player on the far side; a teammate cuts diagonally in front of a mannequin, receives, dribbles past halfway and crosses as three runners attack near post, far post and the back. B: live opponents attack the corner; on a clearance the coach on the far side plays in a new ball.', 'Finish within 10 seconds of the release; reds 1-2 touches except the dribbler; cutting runner has 4-5 seconds to cross.', 'B adds fully active opponents in the box; a white shot or goal means another corner.', 'Quick first movement to receive; explosive support run; passes ahead of runners in stride; free decision making to finish.', '9 v corner attackers', 9, 18, 'Three-quarters of a pitch', NULL, NULL, NULL, true, true, true, NULL, 750),
  ('Corner clearance fast break, full pitch', 'transition', 'passive', 'to_attack', 163, 163, 'Quick Transition to Attack when Defending a Corner Kick: Practice 4', 'Spain national team', 'Same corner-to-counter pattern over a full-length pitch.', 'Full pitch with 4 mannequins in the opposition half.', 'As before: defend the corner, release the far flank and break the length of the field to finish.', 'Finish within 12-14 seconds of the release.', NULL, 'Same points as the three-quarter-pitch version.', NULL, NULL, NULL, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 760),
  ('Corner kick to counter, live game zones', 'transition', 'opposed', 'to_attack', 164, 164, 'Quick Transition to Attack when Defending a Corner Kick: Practice 5', 'Spain national team', 'Defend a corner then counter through set wide zones in a fully live game.', 'Full pitch with 5 areas: areas 1 and 2 on each side 16 x 24 yd, central area 3 32 x 30 yd; both teams live.', 'Whites take a corner; reds defend it and break only via a side area 1, receiving there and dribbling into area 2, then either pass into area 3 or from area 2 into the box. Defenders may not enter the final zone before the ball; every restart is a white corner, alternating sides.', 'Reds 1-2 touches in own half except the area-1 player; 2-3 touches or 3-5 seconds in area 2; 6-10 seconds to finish once in area 2; only one white per side in area 1.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 770),
  ('Passing circle into 1v1 on coach''s call', 'one_v_one', 'opposed', 'to_attack', 168, 168, 'Playing Quickly from Back to Front (Group A): Practice 1', 'Spain national team', 'Quick reactions and dribbling moves to win a 1v1.', '30 x 30 yd area, two full goals with keepers, neutrals on the sidelines, 2 players inside.', 'All six pass freely until the coach calls; the inside player on the ball attacks and the other defends; restart after a goal or ball out.', 'Variations: restart when the defender wins it, or he counters until out of play; attacker touches unlimited or capped; shooting time free or limited.', NULL, 'Stay alert to react to the call and attack or defend at once.', '1v1 + 2 GK + 2 N', 6, 6, '30 x 30 yards', 27.4, 27.4, NULL, true, true, true, NULL, 780),
  ('5-zone possession with 1v1 breakout duels', 'small_sided_game', 'opposed', 'in_possession', 169, 169, 'Session: Practice 2 (Group A)', NULL, 'Keep the ball centrally then break out with a dribble to win a 1v1 and finish quickly.', '48 x 20 yd area split into 5 zones: two 10x20 end zones with goals and keepers, an 18x20 middle zone and two 5x20 1v1 zones. 4v4 in the middle, one defender from each team in each 1v1 zone, two players per team on each sideline.', 'The team in possession (starting from its keeper) keeps the ball in the middle zone until one player dribbles forward into a 1v1; if he beats the defender he shoots within 3 touches. The beaten defender goes to the sideline and a teammate replaces him; meanwhile a side player of the other team dribbles in with a new ball and an attacker also steps in from the side, so play continues. If the defender wins the 1v1 he passes back into the middle and the beaten attacker returns there too.', 'Defenders may not enter the end zones; unlimited touches except 3 in the final zone; coach decides whether passing back to the defender is allowed.', NULL, NULL, '4v4 central + 1v1 zones + side players + 2 GKs', 16, 16, '48 x 20 yards', 43.9, 18.3, NULL, true, true, true, NULL, 790),
  ('9v9 game with coach-called 1v1 / 2v2', 'small_sided_game', 'opposed', 'in_possession', 170, 170, 'Session: Practice 3 (Group A)', NULL, 'Quick reactions, dribbling and creative attacking in 1v1 and 2v2 moments inside a game.', '60 x 40 yd pitch, two goals with keepers, 9v9 both in a 3-2-3 shape.', 'Normal game, but on the coach''s signal the ball carrier plays 1v1 against his direct opponent while everyone else freezes; or he passes to a teammate and they play 2v2 against the two nearest defenders. Coach calls ''1'' or ''2'' to pick the situation.', NULL, 'Free normal game; limit the time for the attackers to finish the 1v1/2v2; or give unlimited time.', NULL, '9v9 + 2 GKs', 20, 20, '60 x 40 yards', 54.9, 36.6, NULL, true, true, true, NULL, 800),
  ('Press, win it and long ball into mini goals', 'transition', 'opposed', 'to_attack', 171, 171, 'Session: Practice 4 (Group B)', NULL, 'Defensive organisation and pressing to win the ball, then a fast counter with an accurate long pass.', 'Half pitch plus a line 3-5 yards past halfway; a full goal with keeper and two small goals in the far half. 8v8 outfield: reds in a 4-4, whites in a 2-4-2 (any shape).', 'Coach passes to the whites, who attack the big goal. Reds defend ball-oriented and, on winning it, must strike a long pass straight into one of the two mini goals. As soon as a red strikes, the coach feeds a new ball to a white on the other side so reds must shift their block across.', 'Reds have 3-5 seconds after winning it to hit the mini goal; reds 2-3 touches, whites unlimited; nobody crosses the red line.', NULL, NULL, '8v8 + GK', 17, 17, 'Half pitch + 3-5 yards', NULL, NULL, NULL, true, true, true, NULL, 810),
  ('Press, win it and long ball to attackers in boxes', 'transition', 'opposed', 'to_attack', 172, 173, 'Session: Practice 5 (Group B)', NULL, 'Win the ball and switch to attack with a quick long pass to forwards waiting in wide boxes.', 'Full pitch, two keepers; same zone and line as before, with two boxes in the far half each holding one red attacker (the 2 forwards of the 4-4-2).', 'A) On winning the ball reds play a long pass into one of the boxes; the attacker controls, dribbles out and passes to a white on the far side, and the passer swaps places with him, so whites counter against an unbalanced red team that must reorganise. B) Two defenders and a keeper are added: the attacker in the box controls and dribbles at goal, beats a 1v1 defender and tries to score. Each time a long ball is in flight the coach feeds whites on the other side so reds shift.', '3-5 seconds to find a boxed attacker after winning it; attackers have 6-8 seconds to finish; reds 2-3 touches, whites unlimited; nobody crosses the red line.', 'Part B adds 2 defenders and a GK so the attacker finishes a 1v1 on goal.', 'Quality first-time long ball; press together and communicate; creativity and finishing in part B.', '8v8 + attackers + 2 GKs', 19, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 820),
  ('Win it low and play long to 2v2 high zone', 'transition', 'opposed', 'to_attack', 174, 174, 'Session: Practice 6 (Group A & B)', NULL, 'Defend in the low zone, win the ball and launch a quick counter with a long pass to two forwards.', 'Full pitch with a 20 x 65 yd neutral zone set 5 yd into one half and 15 yd into the other. Low zone 8v8 (reds 4-4 vs whites 2 full backs, 4 midfielders, 2 attackers); high zone 2v2 (red attackers v two centre backs) with goalkeepers.', 'Whites attack in the low zone; reds defend ball-oriented and on winning it pass quickly to the two attackers in the high zone, who play 2v2 to score. Later, once the ball reaches the high zone all players may move freely to support.', '3-5 seconds to find the attackers after winning it; reds 2-3 touches in low zone, attackers and whites unlimited; attack must finish within 6-12 s of winning it and 6-8 s of the attacker receiving.', 'Progress from a pure 2v2 to everyone joining the attack.', NULL, '8v8 + 2v2 + 2 GKs', 22, 22, 'Full pitch, 20 x 65 yd neutral zone', NULL, NULL, NULL, true, true, true, NULL, 830),
  ('Play quickly through the lines 3-zone SSG', 'small_sided_game', 'opposed', 'in_possession', 176, 177, 'Session: Practice 1', NULL, 'Build up from back to front quickly through the opposition lines.', '32 x 16 yd area in 3 zones (two 9x16 end zones, 14x16 centre) with goalkeepers. End zones 2v2 + 1 neutral, centre 3v3 + 1 neutral; neutrals play for the side in possession.', 'A) Keeper passes to a defender, who moves it quickly into the centre, then into the far end zone, and the aim is to reach the other keeper (not to score); he then restarts with his team in the other direction. B) Neutrals leave the end zones, making 3v2 there; a middle player dribbles into the end zone to make 3v3 and the attackers try to score.', 'Part A: each player max 2 passes, neutrals 1 touch, ball must go keeper to keeper within a set time (e.g. 8-10 s). Part B: 2 passes in low zone, 3 touches in middle, unlimited in final zone.', 'Defenders passive, then high press without tackling, then press only to block passes, then fully active.', 'Check away before receiving; direct passes to feet through the lines; dribble and change direction at speed; good decisions and finishing in part B.', '7v7 + 2 neutrals + 2 GKs', 16, 18, '32 x 16 yards', 29.3, 14.6, NULL, true, true, true, NULL, 840),
  ('Quick back-to-front 3-zone SSG with wide neutrals', 'small_sided_game', 'opposed', 'in_possession', 178, 178, 'Session: Practice 2', NULL, 'Build up quickly through the lines with help from neutral players, two of them giving width.', 'Same 3-zone area as the previous practice plus two neutral players on the sides, allowed in the middle and high zones only, playing for the team in possession.', 'Teams build from the keeper through the zones and attack the far goal, using the wide neutrals to support and stretch play.', 'The attack must finish within 10 seconds.', NULL, 'Final pass well weighted and timed with the run in behind the back line.', 'Teams + 3 neutrals + 2 GKs', 17, 19, '32 x 16 yards', 29.3, 14.6, NULL, true, true, true, NULL, 850),
  ('Win it and break through a 4-zone full pitch', 'transition', 'opposed', 'to_attack', 179, 179, 'Session: Practice 3', NULL, 'Build quickly from back to front through the lines on a full pitch after winning the ball.', 'Full pitch in 4 zones with keepers: 3v2, 4v4 (+1 neutral) and 2v3 in the first three zones; two neutrals on the side who may only move between zones 2 and 3.', 'A team that wins it in zone 1 passes quickly into zone 2; from there a player dribbles into zone 3; from zone 3 a player passes into the space behind the back line for a teammate in zone 4. When an attack ends the roles reverse and the other keeper restarts.', 'Zones 1 and 4: 2 touches; zones 2 and 3: unlimited; win it in zone 1 = 15 s to finish, in zone 2 = 10 s.', NULL, NULL, 'Full teams + 3 neutrals', NULL, NULL, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 860),
  ('11v11 4-zone win it and transition game', 'conditioned_game', 'opposed', 'to_attack', 180, 180, 'Session: Practice 4', NULL, 'Win the ball and attack quickly in a full 11v11 game.', 'Same 4 zones as before with neutrals removed; 11v11, team in possession 4-4-2, defending team 3-4-3, giving 3v4 in zone 3, 4v4 in zone 2 and 3v2 in zone 1.', 'The defending team starts in zone 3 and tries to win the ball, mainly in zones 1-2, then counters with free decision making. The building team starts with a 4v3 advantage at the back.', 'Building team: 2 touches zone 1, 3 touches zone 2, unlimited zones 3-4; defending team: 2 touches zones 1 and 4, unlimited zone 2, 3 touches zone 3; win it in zone 1 = 15 s to finish.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 870),
  ('Counter from 7v9 then switch to defend', 'transition', 'opposed', 'to_attack', 183, 183, 'Session: Practice 1 (Group A)', NULL, 'Win the ball when outnumbered (7v9), counter across goal lines, then switch the point of defence in a quick negative transition.', 'Half pitch with one goal line 5 yd inside halfway and another 75 yd from goal. Reds: keeper + 7 outfield in a 4-3; whites: 9 players in a 4-2-3-1 minus a centre back.', 'Coach feeds the whites, who attack the goal. Reds defend ball-oriented; on winning it they score 1 point for dribbling past the first goal line (whites can chase) and 2 for the far line. Then the coach immediately passes a new ball the other way, and reds must switch their defensive block across while outnumbered.', 'Whites unlimited touches; reds have 6 s to cross the first line and 10 s for the second; if they fail the coach restarts with the whites.', NULL, 'Compact, straight defensive lines; explosive dribbling through the lines; quick reaction to shift across.', '7v9 + GK', 17, 17, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 880),
  ('4v5 (+2) zonal transition game', 'transition', 'opposed', 'to_attack', 184, 184, 'Session: Practice 2 (Group B)', NULL, 'Win the ball while outnumbered and launch a fast break.', '56 x 36 yd area in 3 zones: 32x36 centre, two 12x36 end zones with goals and keepers. Whites have 5 players (2 on each end line plus 1 inside) and 2 outside players; 4 reds inside.', 'Whites keep it aiming for 8-10 passes (1 goal). Reds win the ball and attack either goal fast; when they do, the 2 whites on the nearest line, the inside player and one from the far line defend, giving 4v2 (+1+1) or 4v3 (+1).', 'Whites 2-3 touches, outside players 1 touch; reds unlimited in centre, 2 touches in final zone; 6-10 s to finish after winning it, 4 s once out of the central zone.', NULL, NULL, '4v5 + 2 outside + 2 GKs', 13, 13, '56 x 36 yards', 51.2, 32.9, NULL, true, true, true, NULL, 890),
  ('6v6 quick reactions 2-zone transition game', 'transition', 'opposed', 'to_attack', 185, 186, 'Session: Practice 3 (Group B)', NULL, 'Keep the ball, win it back and attack fast before the opponents reorganise.', '56 x 36 yd area split into two 23 x 36 zones with a goal and keeper at each end. 6v6; team in possession free formation, defenders press in a 2-3.', 'Part 1: whites keep the ball in one zone aiming for 6-8 passes (1 point); reds press to win it, then pass to their keeper, who plays to a red; all players then race into the other zone and reds attack. Part 2: only whites who get back before all 5 reds can defend; scenario 1 those whites may defend across both zones, scenario 2 they must stay in grid 2 (e.g. 5v3 then 5v2). After a goal or ball out, restart from the other side with roles swapped.', 'Starting team unlimited touches; defenders who win it 2 touches until the GK pass; reds finish within e.g. 10 s after the GK pass; red goal = 3 points; in part 2 whites in the second grid cannot drop back.', 'Part 2 with two scenarios.', 'Quick reactions and awareness; attack at pace with forward passes before the other team reorganises.', '6v6 + 2 GKs', 14, 14, '56 x 36 yards', 51.2, 32.9, NULL, true, true, true, NULL, 900),
  ('4v3 (+1) fast break 3-zone full pitch', 'transition', 'opposed', 'to_attack', 187, 187, 'Session: Practice 4 (Group A & B)', NULL, 'Keep the ball, win it and attack quickly in a 4v3 (+1) fast break.', 'Full pitch in 3 zones: low zone with red keeper + 7 outfield (4-3) v 8 whites (2 full backs + 2-3-1); the other zone holds 3 red attackers v 3 white defenders and the white keeper.', 'Whites (8v7) attack the low-zone goal; reds defend ball-oriented and on winning it one red dribbles into the next zone, followed by one white, creating 4v3 (+1). All players may then move to the final zone (whites only once the ball is there).', 'Reds must finish within 8 seconds; the ball must be dribbled into the next zone within 6-8 s.', NULL, 'Rehearsed combination play; good shape and collective pressing; quick dribbling; quick decisions and finishing.', '11v11 incl. GKs', 20, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 910),
  ('Fast break 1v1 (+2v2) duel', 'one_v_one', 'opposed', 'to_attack', 189, 190, 'Session: Practice 1', NULL, 'Fast breaks with support players in a 1v1 (+2v2) situation.', '40 x 20 yd area, two full goals with keepers, two pairs of players beside each goal, two neutral players on the sides and two players inside.', 'The neutrals, inside players and keepers pass the ball around while waiting. On the coach''s signal whoever has the ball attacks and the other defends; the two pairs on the attacker''s side join in for a 1v1 (+2v2). After a goal or ball out, a new pair starts inside.', NULL, 'Variation (Practice 2): no neutrals; keepers numbered 1 and 2 each with a ball; the coach calls a number and that keeper passes to his teammate to start the duel.', 'Side players stay focused to support quickly; encourage creative combinations.', '2 inside + 2 neutrals + 4 pairs + 2 GKs', 14, 14, '40 x 20 yards', 36.6, 18.3, NULL, true, true, true, NULL, 920),
  ('Dynamic 3v3 quick transition game', 'small_sided_game', 'opposed', 'to_attack', 191, 192, 'Session: Practice 3', NULL, 'Quick reactions and fast transitions to finish attacks.', '40 x 20 yd area, two goals with keepers, 3v3 inside and two pairs of players beside each goal.', 'Free 3v3; when an attack ends the coach passes a new ball to a player of the other team, who stays in with his direct opponent while the other pairs leave; the two pairs at the nearest end come in, so a continuous 1v1 (+2v2) game runs.', NULL, 'Variation (Practice 4): sideline players replaced by 4 poles; players numbered 1-3; when an attack ends the coach calls a number, that pair stays and receives the ball while the other two pairs run round a pole and rejoin.', 'Combinations of 2-3 players such as overlaps; good dribbling and changes of direction; quick decisions and finishing; manage intensity, duration and rest.', '3v3 + side pairs + 2 GKs', 12, 16, '40 x 20 yards', 36.6, 18.3, NULL, true, true, true, NULL, 930),
  ('Outnumbered possession 2-zone transition game', 'possession', 'overload', 'to_attack', 195, 196, 'Session: Practice 1', NULL, 'Passing and movement to keep the ball and transition quickly when outnumbered.', '50 x 45 yd area split into two 25 x 45 zones. Teams of 10 (whites) and 8 (reds).', 'Play starts with 6 reds v 7 whites in one zone; reds try to win it and pass to 2 teammates in the other grid. Then 2 more reds and 3 whites move across, giving 4 reds v 6 whites with reds in possession; reds keep it as long as possible. If they lose it, 1 white and 2 reds cross back and the 6v7 restarts.', 'Whites 2-3 touches, reds unlimited; whites 6-8 passes = 1 point; reds 4-6 passes = 1 point, keep it 10 s = 2 points.', NULL, 'Press together when outnumbered; shield the ball; check away before receiving; quick support movement.', '10v8', 18, 18, '50 x 45 yards', 45.7, 41.1, NULL, false, false, false, NULL, 940),
  ('Outnumbered possession 3-zone transition game', 'possession', 'overload', 'to_attack', 197, 197, 'Session: Practice 2', NULL, 'Keep possession and transition while outnumbered across three zones.', '60 x 30 yd area in three 20 x 30 zones; 10 whites and 9 reds: 5v5 in zone 1, 2v3 in the middle, 2v2 in zone 3.', 'Whites start in zone 1 aiming for 6-8 passes; reds press and on winning it pass to their two teammates in the middle while 2 reds and 2 whites cross over (4v5). Reds aim for 4-6 passes or 6-8 s, then pass to the far grid where 1 red and 2 whites move across (3v4); they keep it 6-8 s then pass back to the middle. The game is continuous; losing it outside creates 5v5 there.', 'Whites 2-3 touches, reds unlimited; whites 6 passes = 1 point; reds 4-6 passes = 1 point; keep it 10 s = 2 points.', NULL, NULL, '10v9', 19, 19, '60 x 30 yards', 54.9, 27.4, NULL, false, false, false, NULL, 950),
  ('Outnumbered 3-zone transition game full pitch', 'transition', 'overload', 'to_attack', 198, 198, 'Session: Practice 3', NULL, 'Win the ball low, then keep it under a numerical disadvantage in the opposition half before attacking.', 'Full pitch in 3 numbered zones with keepers. Reds: 9 in zone 1 and 2 in zone 2; whites: 7 in zone 1 and 3 defenders in zone 2.', 'Whites attack the red goal from zone 1; reds win it and pass or dribble into zone 2, where 2 reds and 4 whites may cross over. Reds must complete 4-5 passes or keep it 10 s at 4v7 before they may enter zone 3 and attack the goal.', 'Reds unlimited touches in zone 1 but must reach zone 2 within 6-8 s of winning it; unlimited in zone 2, 2 touches in zone 3; whites unlimited.', NULL, 'Collective ball-oriented defence low; keep the ball under pressure in their half; attack the weak side when possible.', '11v11 incl. GKs', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 960),
  ('Curved outside run to receive in behind', 'passing_unopposed', 'unopposed', 'in_possession', 204, 205, 'Session: Practice 1', NULL, 'Check away from a marker, quick combination play and running with the ball.', 'Pairs in a 15 yd long area with two mannequins 2 yd apart in the middle.', 'A) Player 1 dribbles towards the mannequins, passes to player 2, curves round a mannequin and receives a first-time pass in behind, then dribbles back; roles swap. B) With 4 players player 1 dribbles on and passes to player 3 and switches sides; a continuous loop where the coach changes direction.', NULL, 'Variation (Practice 2): player 1 starts without the ball, gets a set and return from player 2 and then makes the curved run for a pass into space.', 'Open body shape, receive with back foot; right surface for the distance; anticipate next move; pass accuracy, weight and communication.', '2-4 players', 2, 4, '15 yards long', 13.7, NULL, NULL, false, false, true, NULL, 970),
  ('Inside / outside run passing combination', 'passing_unopposed', 'unopposed', 'in_possession', 206, 207, 'Session: Practice 3', NULL, 'Rehearse attacking combinations with inside cutting and curved outside runs.', '8 players on 7 cone positions; part B adds two mannequins at position 4 on both sides.', 'A) 1 passes to 2, 2 to 4 while 3 cuts inside; 4 feeds 3, who passes back to the start. B) 1 to 2, 2 to 3 and back, 2 passes into space for 4''s curved outside run round the mannequins; 4 dribbles and finds 3 running round the mannequins, who returns it to the start. Runs both ways, players rotate a position.', '1-2 touches or 1 touch.', NULL, 'Accurate, well-timed passes; right surface for the distance; anticipate the next movement.', '8 players', 8, 8, NULL, NULL, NULL, NULL, false, false, true, NULL, 980),
  ('Curved outside run combination and shot', 'combination', 'unopposed', 'in_possession', 208, 208, 'Session: Practice 4', NULL, 'Finish an attacking combination with a curved outside run and a first-time shot.', 'Same positions and mannequins as before with a full goal and goalkeeper added.', 'Keeper passes to player 1, who plays into the space for player 3''s unmarking run; 3 dribbles on and passes to player 2 making an inside cutting run, who shoots first time. Runs from both sides; players rotate.', NULL, NULL, 'Player 3''s timing sets the rhythm; pass accuracy, weight and communication.', '7-8 + GK', 8, 9, NULL, NULL, NULL, NULL, true, true, true, NULL, 990),
  ('Inside and outside runs 2v1 and finish', 'one_v_one', 'opposed', 'to_attack', 209, 209, 'Session: Practice 5', NULL, 'Combine inside and curved outside runs to create and finish a 2v1.', '50 x 25 yd area with two full goals and keepers and a 10 yd zone marked in the middle; attackers and defenders start as in the diagram, coach with balls on the side.', 'Two attackers pass to each other; while the ball travels the coach signals and a defender runs in front of the receiver. The receiver passes into space for his partner, while the other attacker from the side makes an inside curved opposite run, giving 2v1 at goal. Then sides swap.', 'Finish within a set time (e.g. 6 s).', NULL, NULL, '6 players + 2 GKs', 6, 8, '50 x 25 yards', 45.7, 22.9, NULL, true, true, true, NULL, 1000),
  ('7v7 3-zone curved run and pass out wide', 'small_sided_game', 'opposed', 'to_attack', 210, 210, 'Session: Practice 6', NULL, 'Keep the ball, win it and play quickly out wide for a curved run and finish.', '60 x 30 yd area in three 20 x 30 zones with goals and keepers. 5v5 in the centre (4 midfielders and 1 attacker each, 4-1-3-2 or 4-4-2) plus an extra attacker per team in each final zone; 8 cones make 2 gates for each attacker.', 'The team in possession aims for 6-8 passes before passing to its attacker in the final zone; then all may enter, but the attacker cannot shoot until a teammate has touched it there. Defenders win the ball and break: one player runs forward from the centre and the attacker, having received through his gate, passes across for a first-time finish.', 'At first defenders may not enter the final zone (then allow one); central zone unlimited or 2-3 touches; after winning it reach the final zone within 4 s or lose the ball; attackers 2 touches in the final zone.', 'Progress to 1 defender allowed in the final zone.', NULL, '7v7 + 2 GKs', 16, 16, '60 x 30 yards', 54.9, 27.4, NULL, true, true, true, NULL, 1010),
  ('Middle zone curved run and pass out wide 3-zone game', 'conditioned_game', 'opposed', 'to_attack', 211, 211, 'Session: Practice 7', NULL, 'Win the ball in the middle zone and play quickly to an attacker for a curved run and finish.', 'Full pitch with a goal on the edge of the box and 3 zones. Whites 4-1-4-1, reds/blues 4-1-3-2; 9v9 in the centre and 1v1 in the high zone. Defending team = 6 reds + 3 blues; only blues may enter the final zone in transition.', 'Whites attack; reds and blues defend in the centre. Whites can pass into the end zone where no red/blue may follow. Reds win it in the centre and pass to the high-zone attacker in the space left or right of him; one blue can move up in support while 1 white drops in to defend; then progress to everyone allowed in the final zone.', 'Whites unlimited in centre, 2 touches in zone 1; reds/blues 2 touches in centre, unlimited in high zone; blues 1-touch finish; reds have 4 s to reach the high zone and 10 s to finish.', 'Progress to all players allowed into the final zone.', NULL, '10v10 + GKs', 20, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 1020),
  ('4-team 3-zone gauntlet: win it and pass', 'transition', 'opposed', 'to_attack', 213, 213, 'Session: Practice 1 (Group A)', NULL, 'Win the ball, pass quickly to start a counter, and keep and pass the ball in behind a defensive line.', '75 x 40 yd area in three 25 x 40 zones, 4 teams of 6 and a coach on each side of the middle zone. In zone 1 reds defend in a 4-2 (4 defenders, 2 centre mids) against whites in a 2-3-1 or 4-2/4-1-1-1.', 'Whites try to get past the end line behind the reds by dribbling or receiving in behind (2 points). Reds defend ball-oriented and on winning it pass to a side coach (1 point); the coach then feeds blues in the next grid and reds move up to defend against them with the same aims, and then again against yellows in zone 3. Getting in behind a line without losing the ball = 1 point. When the reds'' attack ends, all teams switch roles.', '5 seconds to pass to a coach after winning it; attackers unlimited (or 2-3) touches.', NULL, NULL, '4 teams of 6', 24, 24, '75 x 40 yards', 68.6, 36.6, NULL, false, false, true, NULL, 1030),
  ('4-team 3-zone gauntlet with mini goals', 'transition', 'opposed', 'to_attack', 214, 214, 'Session: Practice 2 (Group A)', NULL, 'Win the ball and counter quickly, now finishing in mini goals.', 'Same 75 x 40 yd area with 3 mini goals at each end. Reds defend the mini goals in zone 1, stop blues dribbling over the line in zone 2 and stop yellows passing into the middle zone in zone 3.', 'Reds win it in zone 1 and pass to the blues, then sprint up to defend them; winning it in zone 2 they pass to a side coach within 5 s, and the other coach immediately plays a long ball to the yellows in zone 3. If reds win it in zone 3 they try to score in one of the 3 mini goals. Then all teams change roles.', 'Same as previous; in zone 3 finish within 10 s with unlimited touches.', NULL, NULL, '4 teams of 6', 24, 24, '75 x 40 yards', 68.6, 36.6, NULL, true, false, true, NULL, 1040),
  ('Dribble inside, runs in behind pattern (4-4-2)', 'combination', 'unopposed', 'in_possession', 215, 215, 'Session: Practice 3 (Group B)', 'Spain (v Belgium goal)', 'Ball carrier dribbles inside while teammates time runs in behind the back line for a through ball and finish.', '50 x 40 yd area, full goal with keeper, 5 mannequins and a line 18 yd from goal. 5 players: centre mid, left mid, right mid and 2 strikers.', 'Keeper plays long to the centre mid (6), who controls and passes at once to the left mid (11). He dribbles inside while the others make set runs: option 1 the far wide mid (7) receives centrally, option 2 the striker (9) receives on the left with 7 to the far post, 10 near post and 11 from behind, option 3 a 1-2 with the attacking mid (10) before the shot. The carrier chooses. If the keeper starts via the other centre mid (8), it runs the mirror image from the right.', NULL, NULL, NULL, '5 + GK', 6, 6, '50 x 40 yards', 45.7, 36.6, NULL, true, true, true, NULL, 1050),
  ('Dribble inside, pass in behind 6v5 zonal game', 'phase_of_play', 'opposed', 'to_attack', 216, 216, 'Session: Practice 4 (Group B)', NULL, 'Apply the dribble-inside and pass-in-behind movement in a 5v6 zonal game.', '3 zones: a 10 x 40 zone with 2 mini goals, a 30 x 40 middle zone and an 18 x 40 zone with a full goal and keeper. 5 white defenders: 3 in the middle zone, 2 in the high zone.', 'Keeper plays long to the final zone where 2 red centre mids face 2 white pressers who block passes to the wide mids; if whites win it they attack the 2 mini goals. If reds get the ball into the middle zone, the 4 there attack 4v3 (+1 white returning from the low zone), aiming to slide a teammate in behind the back line using the pattern.', 'First phase is just 2v2, nobody else enters the low zone; if whites win it in zone 2 it becomes a normal game; red centre mids unlimited touches; once in the middle zone reds finish within 8-10 s.', NULL, NULL, '6v5 + GK', 12, 12, '58 x 40 yards', 53.0, 36.6, NULL, true, true, true, NULL, 1060),
  ('Win it in midfield, pass in behind 8v8', 'positional_game', 'opposed', 'to_attack', 217, 217, 'Session: Practice 5 (Group A & B)', NULL, 'Win the ball in the middle zone and pass straight in behind the defensive line.', '75 x 55 yd area in 3 zones: 55 x 55 middle, two 10 x 55 end zones. Two teams of 8 in a 4-4; the 4 defenders and 2 centre mids wear team colours, wide mids on both sides wear a different colour.', 'Teams defend ball-oriented to stop passes into the end zone behind them. On winning it, a team breaks at once by passing in behind at the other end; only the wide mids may receive in the end zones.', 'Score by dribbling into, or passing to a teammate who controls in, the end zone; team in possession unlimited touches and time, team in transition 2-3 touches and 8 s to attack.', NULL, NULL, '8v8', 16, 16, '75 x 55 yards', 68.6, 50.3, NULL, false, false, true, NULL, 1070),
  ('Win it in the middle, counter in 5-zone full pitch', 'conditioned_game', 'opposed', 'to_attack', 218, 218, 'Session: Practice 6 (Group A & B)', NULL, 'Win the ball in the middle zone and attack quickly in behind in the final third.', 'Full pitch with a middle defensive zone split into 1a and 1b, plus a line 10 yd outside the white penalty area. Whites 4-2-3-1 with keeper; reds 4-4-2 with a bowl.', 'White keeper starts and whites try to keep it and score at the other end; reds start defending when the ball enters 1b. Winning it in 1b reds attack with the rehearsed combinations; winning it in 1a they must first pass to teammates in 1b, then attack the same way.', 'White defenders may not enter zone 3 before the ball; whites unlimited touches; reds 2 touches in 1a and 3, unlimited in 1b and 2; win in 1a = 10-12 s to finish, in 1b = 8-10 s; red defenders cannot drop into the low zone until whites pass there.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 1080),
  ('Break through the centre, flank cross and finish', 'transition', 'opposed', 'to_attack', 221, 221, 'Session: Practice 1', NULL, 'Quick dribbling through the centre, a pass into space out wide and timed runs into the box.', '60 x 40 yd area in three 20 x 40 zones, full goals and keepers at each end, 6 large cones making 3 gates in the middle zone and 4 poles making 2 more gates. 5v5 in the first zone; 2 white players with a ball each on the sides, 2 red defenders and 2 red attackers.', 'Whites attack; the 5 reds defend and on winning it a red dribbles past the first line, chased by one white only. If he dribbles through a gate the white stops, he passes left or right to a red attacker outside while the other makes an opposite run through the poles, and the cross is finished. As he goes through, a white side player brings a new ball and a red from the side becomes a defender so 5v5 restarts.', NULL, NULL, 'Dribble at high speed away from the opponent; correct weight of cross and well-timed run.', '5v5 + side players + 2 GKs', 14, 16, '60 x 40 yards', 54.9, 36.6, NULL, true, true, true, NULL, 1090),
  ('5v5 (+4) counter with wide support, mini goals', 'small_sided_game', 'opposed', 'to_attack', 222, 223, 'Session: Practice 2', NULL, 'Fast break attacks with combination play: dribbling through the centre, passing into space and timed runs into the box.', '50 x 25 yd area with 2 mini goals at each end; 5v5 plus 4 neutral players in set positions (part 1).', 'One team (+2 neutrals) keeps it in one half; reds defend their 2 mini goals and on winning it counter with the neutrals'' help to score at the opposite end. Then reds start in possession and the 4 neutrals switch positions (part 2).', 'Inside players 3 touches (progress to 2); neutrals 1 touch.', 'Part 2 swaps the neutrals'' positions; go from 3 to 2 touches.', 'Coordinated runs to meet the final ball (one to each goal, one behind) like near/far post runs; counter at high pace with everyone supporting; quality final balls and finishing.', '5v5 + 4 neutrals', 14, 14, '50 x 25 yards', 45.7, 22.9, NULL, true, false, true, NULL, 1100),
  ('8v8 2-zone counter with wide support players', 'small_sided_game', 'overload', 'to_attack', 224, 224, 'Session: Practice 3', NULL, 'Win the ball while outnumbered and launch a quick counter out wide.', '8v8 on two halves with full goals and keepers. Whites: 4 in the opposition half (+2 outside at the end) and 2 in their own half; reds: 4 defending in their half, 2 in the opposition half and 2 wide support players left and right.', 'Reds'' 4 defenders protect the goal, then on winning it launch a fast break: only one player may dribble forward into the other half, giving 3v2 (+2) using the wide support players to cross and finish.', 'White attackers cannot track back; reds 2-3 touches in transition; side players 2 touches; set a time limit to finish (e.g. 8 s).', NULL, NULL, '8v8 + 2 GKs', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 1110),
  ('Full pitch 11v11 counter attack via wide supports', 'conditioned_game', 'opposed', 'to_attack', 225, 225, 'Session: Creating a Numerical Advantage in the Centre & Quick Counter Attack using the Flank - Practice 4 (Progression)', 'Spain (2008-12)', 'Winning the ball in midfield and breaking quickly through wide support players to cross and finish.', 'Full pitch split in 3 zones: an 8v8 central zone and a safety zone at each end; two neutral-style wide support players stand outside the zones in each corner; keepers in both goals.', 'White team attacks in a 4-2-3-1 while reds defend in a 4-4-2 in the middle zone, no reds allowed in the white safety zone. When reds win the ball they must find a wide support player quickly, who crosses for runners arriving from the middle zone; once reds have the ball all reds may enter the end zone to finish.', 'Team in transition has 10-12 seconds to finish; wide supports 2 touches and cannot enter zones; unlimited touches in middle zone, 2 in end zones; ball must reach a wide player within 4-6 seconds of winning it.', NULL, NULL, '11v11 (8v8 in middle + wide supports)', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 1120),
  ('12v7 regain-and-press game, no keepers', 'transition', 'overload', 'to_defend', 230, 230, 'Session: Quick Pass in Behind the Defensive Line after Regaining Possession - Practice 1', 'Spain (2008-12)', 'Closing down space immediately after losing the ball and winning it back, plus keeping possession.', '40 x 20 yard area with a full size goal (no keeper) at each end. Whites: 7 inside. Reds: 12 (4 inside, 8 spread round the outside).', 'Reds keep the ball, scoring 1 point for 8 passes or 2 for 30 seconds of possession. When whites win it, all reds can enter and must press fast to stop forward passes and shots; whites score 1 point if reds fail to regain within 6-8 seconds, 2 points for a goal; reds regaining in time return to possession.', 'Rule options: red outside players 2 touches / inside unlimited; outside 1 touch, inside 2-3; reds finish first time; whites unlimited or 2-3 touches.', NULL, NULL, '12v7', 19, 19, '40 x 20 yards', 36.6, 18.3, NULL, true, false, true, NULL, 1130),
  ('12v7 regain game with keepers and gates', 'transition', 'overload', 'to_defend', 231, 231, 'Session: Quick Pass in Behind the Defensive Line after Regaining Possession - Practice 2 (Progression)', 'Spain (2008-12)', 'Faster reaction to losing the ball when the opponents have more ways to score.', 'Same 40 x 20 area as the 12v7 game, now with goalkeepers in both goals and 5 cone gates spread across the pitch.', 'Whites who win the ball score 1 point for a pass to a team-mate through a gate, 2 for dribbling through a gate and 3 for a goal. Reds keep their possession targets but must press even quicker to cover the extra options.', NULL, NULL, 'Close the ball carrier fast and create an overload around the ball; stay alert and read the changing picture.', '12v7 + 2 GKs', 21, 21, '40 x 20 yards', 36.6, 18.3, NULL, true, true, true, NULL, 1140),
  ('9v9 regain and fast break with outside players', 'transition', 'opposed', 'to_attack', 232, 232, 'Session: Quick Pass in Behind the Defensive Line after Regaining Possession - Practice 3 (Progression)', 'Spain (2008-12)', 'Pressing to regain the ball, then fast combination play to finish the counter attack.', 'Full pitch with a 32 x 32 yard central zone; keeper in each goal. 8v8 outfield: 4 per team inside the centre zone, the other 4 positioned outside it (2 at each end).', 'Whites keep the ball in the centre zone (1 point per 8 passes). The 4 red insiders press; on winning it they pass out to their outside players, who attack either goal while the white outside players defend.', NULL, 'Variation (Practice 4): change starting positions of outside players to create a 2v1 counter.', 'Final pass timed and weighted for the run in behind; outside players react fast to get into position to attack or defend.', '9v9 incl. GKs', 18, 18, 'Full pitch, 32 x 32 yard centre zone', 29.2, 29.2, NULL, true, true, true, NULL, 1150),
  ('9v9 regain and 2v1 fast break', 'transition', 'opposed', 'to_attack', 233, 233, 'Session: Quick Pass in Behind the Defensive Line after Regaining Possession - Practice 4 (Variation)', 'Spain (2008-12)', 'Quick counter attacks finished at pace from a 2v1 after winning the ball.', 'Same as the previous 9v9 game but the outside players start in different places so the red counter attack becomes a 2v1.', 'Whites keep the ball in the centre zone; reds win it and break with outside players into a 2v1 towards goal, finishing within 6-8 seconds.', 'Finish within 6-8 seconds.', NULL, 'Vary attacking combinations; dribble at speed; quality finishing.', '9v9 incl. GKs', 18, 18, 'Full pitch, 32 x 32 yard centre zone', 29.2, 29.2, NULL, true, true, true, NULL, 1160),
  ('4 zone 11v11 fast break transition game', 'conditioned_game', 'opposed', 'to_attack', 234, 234, 'Session: Quick Pass in Behind the Defensive Line after Regaining Possession - Practice 5 (Progression)', 'Spain (2008-12)', 'Building up play and reacting to losing or winning the ball with quick attacks on a full pitch.', 'Full pitch 11v11 (reds 4-4-2/4-3-3, whites 4-2-3-1/4-4-2) split into zones incl. a middle zone, a small zone just outside the box and a final zone.', 'Scenario 1: reds build from their keeper, score 1 for 8 passes in the middle zone, 2 for a goal; whites who win it score 1 for passing into the small zone, 2 into the final zone, 3 for a goal; reds regaining have 6-8 seconds to finish. Scenario 2: whites start from their keeper, reds press in the middle zone and must counter within 6-8 seconds.', 'Scenario 1: reds unlimited (or 3) touches in middle, 2-3 elsewhere; whites unlimited; whites press once ball enters middle zone. Scenario 2: reds 2-3 touches, whites unlimited.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 1170),
  ('Rondo breakout to 4 goals scenarios', 'transition', 'overload', 'to_attack', 236, 236, 'Session: Breaking from the Middle Zone: Exploiting the Weaknesses in the Opposition Defence - Practice 1', 'Spain (2008-12)', 'Winning the ball while outnumbered, breaking out fast and choosing the best attacking option.', '60 x 60 yard area with a goal and keeper on each side; central 15 x 15 yard square with 5 reds v 3 blue defenders. Outside: goal 1 has a 2v2, goal 2 a 1 defender, goal 3 a 1v1, goal 4 keeper only.', 'Reds play keep-ball in the square. When the 3 blues win it, one dribbles (later dribbles or passes) out towards the goal of his choice, creating a 3v2, 1v1, 2v1 or 1v1 with the keeper depending on the goal.', NULL, 'Allow passing out of the square as well as dribbling.', 'Recognise the game situation and make fast, quality decisions.', '5v3 rondo + outside players + 4 GKs', NULL, NULL, '60 x 60 yards, 15 x 15 yard centre square', 54.8, 54.8, NULL, true, true, true, NULL, 1180),
  ('3 team possession then fast break on signal', 'transition', 'overload', 'to_attack', 237, 237, 'Session: Breaking from the Middle Zone: Exploiting the Weaknesses in the Opposition Defence - Practice 2 (Progression)', 'Spain (2008-12)', 'Fast break attacks with good decisions and well-timed, weighted forward passes.', '50 x 35 yard area split into two 25 x 35 halves, full goals with keepers; 3 teams of 5 (reds, whites, blue neutrals placed round the edge).', 'Reds and whites play keep-ball in one half with help from the neutrals. On the coach''s signal the team in possession attacks the goal in the other half quickly without the neutrals. Rotate team roles after a few goes.', 'Possession: unlimited touches, neutrals 1 touch. Fast attack: 2-3 touches and one-touch finish.', NULL, NULL, '5v5+5 + 2 GKs', 17, 17, '50 x 35 yards', 45.7, 32.0, NULL, true, true, true, NULL, 1190),
  ('3 team fast break game with numbered zones', 'transition', 'overload', 'to_attack', 238, 238, 'Session: Breaking from the Middle Zone: Exploiting the Weaknesses in the Opposition Defence - Practice 3 (Variation)', 'Spain (2008-12)', 'Reading whether the attack is into an open or closed pitch and reacting quickly.', 'Same 3-team set-up as the previous practice but the two halves are numbered 1 and 2.', 'Play starts in zone 1. The coach calls a number: the team in possession must attack in that zone, either an open pitch (other half) or a closed one (the same crowded half). The coach can call 1 then 2 a few seconds later to switch from closed to open.', 'As previous, but unlimited touches when attacking in the closed zone.', NULL, 'Recognise the situation fast and make good decisions.', '5v5+5 + 2 GKs', 17, 17, '50 x 35 yards', 45.7, 32.0, NULL, true, true, true, NULL, 1200),
  ('8v8 numbers called, exploit the gaps', 'small_sided_game', 'opposed', 'to_attack', 239, 239, 'Session: Breaking from the Middle Zone: Exploiting the Weaknesses in the Opposition Defence - Practice 4 (Progression)', 'Spain (2008-12)', 'Vision and decision making to exploit free space in a disorganised defence on the counter.', 'Same area as the previous practices, 8v8 with goalkeepers; each outfield player numbered 1-7.', 'When the ball goes out or a team loses it, the coach calls 2 numbers; those 2 players of the team that lost it must freeze until the next call. The team winning the ball always counters with a 7v5 and must spot and attack the gaps.', 'Counter attacking team limited to 3 touches (then 2); attack must be finished within a time limit.', NULL, NULL, '8v8 incl. GKs', 16, 16, '50 x 35 yards', 45.7, 32.0, NULL, true, true, true, NULL, 1210),
  ('11v11 fast breaks with numbers frozen behind ball', 'conditioned_game', 'opposed', 'to_attack', 240, 240, 'Session: Breaking from the Middle Zone: Exploiting the Weaknesses in the Opposition Defence - Practice 5 (Progression)', 'Spain (2008-12)', 'Recognising and exploiting numerical situations on a full-pitch counter attack.', 'Full pitch 11v11, reds 4-4-2 v whites 4-2-3-1 or 4-3-3; normal game with focus on defending in the middle zone.', 'When a team wins the ball in the middle zone the coach shouts a signal; all players behind the ball stop, so only those ahead of it play on (e.g. 5v5). Attackers dribble forward, combine quickly and make runs in behind to finish fast.', NULL, 'Allow 2 extra players from the attacking team to join (e.g. 7v5).', NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 1220),
  ('6v5 four zone possession with neutrals', 'possession', 'overload', 'in_possession', 249, 249, 'Session: Transition from Attack to Defence & then Defence to Attack - Practice 1', 'Spain (2008-12)', 'Keeping the ball in tight areas and switching play quickly to the weak side.', '50 x 50 yard area split into four 25 x 25 zones; 2 teams of 5 start in one zone and a neutral stands in each zone.', 'The team in possession makes 6 passes then plays to a neutral in another zone and everyone moves there to repeat (1 point per switch, 5 bonus for completing all 4 zones). Defenders who win it can keep the ball in that zone or switch out.', 'Ball and players can move between any zones; players unlimited (or 2-3) touches, neutrals 2 touches (or 1).', NULL, 'Accurate short passes; open body shape and receive/pass with the back foot; quick switches of play.', '5v5+4 (6v5 in zone)', 14, 14, '50 x 50 yards', 45.7, 45.7, NULL, false, false, false, NULL, 1230),
  ('6v6 regain game to 4 numbered goals', 'transition', 'opposed', 'to_defend', 250, 250, 'Session: Transition from Attack to Defence & then Defence to Attack - Practice 2 (Progression)', 'Spain (2008-12)', 'Possession, winning the ball back fast after losing it, quick reactions and finishing.', '50 x 50 yard square with a numbered goal and keeper on each side (1-4); an inner square of 4 grids of 15 x 15 yards.', '6v6 in the inner square: 1 point for 6-8 passes, 2 points for regaining the ball in the same grid it was lost. The coach then calls a goal number and the team that has just won it attacks that goal for 3 points.', 'Options: all unlimited touches; unlimited in grids and 1-2 at goal; 2-3 in grids and 1 at goal.', 'Coach can call a different goal if a team struggles, forcing a fast switch of the point of attack.', NULL, '6v6 + 4 GKs', 16, 16, '50 x 50 yards, 4 grids of 15 x 15', 45.7, 45.7, NULL, true, true, true, NULL, 1240),
  ('4 zone 7v7 regain and score small sided game', 'small_sided_game', 'opposed', 'to_defend', 251, 251, 'Session: Transition from Attack to Defence & then Defence to Attack - Practice 3 (Progression)', 'Spain (2008-12)', 'Pressing straight after losing the ball high up and finishing quickly after regaining it.', '50 x 50 yard area split into four 25 x 25 grids; full goal and keeper at each end.', 'Normal 7v7, 1 point per goal. A team that loses the ball gets 2 points for winning it back in the same grid and 3 points for scoring within 6-8 seconds of regaining it.', 'Options: unlimited touches; unlimited in normal play and 2-3 when countering; 2-3 touches for all with first-time finishes.', NULL, 'Press quickly where the ball is lost; finish fast when regained high.', '7v7 incl. GKs', 14, 14, '50 x 50 yards', 45.7, 45.7, NULL, true, true, true, NULL, 1250),
  ('5 zone 9v9 high press regain game', 'small_sided_game', 'opposed', 'to_defend', 252, 252, 'Session: Transition from Attack to Defence & then Defence to Attack - Practice 4 (Progression)', 'Spain (2008-12)', 'Pressing in the high zone after losing the ball and scoring quickly on the regain.', '45 x 30 yard area split into 5 zones (4 high grids plus a back zone); reds 2-2-3-1, whites 4-4 diamond, keepers in both goals.', 'Reds start from their keeper in a free game. On losing it they press in the 4 high grids: 2 points for winning it back in the same grid, 3 for scoring within 6-8 seconds. Reds get 1 point for a normal goal, whites 2 points for any goal.', 'Options: all unlimited; reds 2-3 touches when countering; reds always 2-3 touches; reds 2-3 touches and one-touch finish.', NULL, NULL, '9v9 incl. GKs', 18, 18, '45 x 30 yards', 41.1, 27.4, NULL, true, true, true, NULL, 1260),
  ('7 zone 11v11 counter-press game', 'conditioned_game', 'opposed', 'to_defend', 253, 253, 'Session: Transition from Attack to Defence & then Defence to Attack - Practice 5 (Progression)', 'Spain (2008-12)', 'Fast regains where the ball is lost and quick finishing on a full pitch.', 'Full pitch, 6 marked zones plus a red safe zone near the red goal; reds 4-4-2 or 4-2-3-1 v whites 4-2-3-1 or 4-4-2 diamond.', 'Reds build from their keeper and try to score; on losing it they win it back in the same grid and then must finish within 8 seconds (zone 2) or 4-6 seconds (zone 1). Whites score 1 point by passing into the safe zone and 2 for a goal.', 'Reds may use the safe zone in possession, whites may not; whites may play in it once the ball is there.', NULL, 'Anticipate and decide fast after regaining; press where the ball is lost.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 1270),
  ('One-two combinations with passive pressing', 'passing_opposed', 'passive', 'in_possession', 255, 255, 'Session: Winning the Ball & One-Two Combination High Up the Pitch - Practice 1', 'Spain (2008-12)', 'Running with the ball, pressing and one-two combinations.', '25 x 25 yard area, 2 teams of 5 spread around.', 'A red dribbles, passes to a white and follows to press passively. The white dribbles at him, a team-mate comes to support and they play a 1-2 past the presser; the white then passes to a red and it repeats.', NULL, NULL, 'Quality first touch to set up the 1-2; support angle; weight and accuracy of the first pass so the return is first time into space; press at high pace like a centre back.', '5v5', 10, 10, '25 x 25 yards', 22.9, 22.9, NULL, false, false, false, NULL, 1280),
  ('Directional one-twos with passive pressing to goals', 'passing_opposed', 'passive', 'in_possession', 256, 256, 'Session: Winning the Ball & One-Two Combination High Up the Pitch - Practice 2 (Progression)', 'Spain (2008-12)', 'One-two combinations played in the direction of play, as in a game.', '35 x 25 yard area with a full size goal at each end; same 5v5 as before.', 'Same pass, press and 1-2 sequence as the previous practice but now played towards the goals.', NULL, 'Add 2 keepers: after the 1-2 the player passes to the opposing keeper, who restarts by rolling or passing to a team-mate.', NULL, '5v5 (+2 GKs)', 10, 12, '35 x 25 yards', 32.0, 22.9, NULL, true, true, true, NULL, 1290),
  ('Dribble, one-two round mannequin and shoot', 'combination', 'passive', 'in_possession', 257, 257, 'Session: Winning the Ball & One-Two Combination High Up the Pitch - Practice 3 (Progression)', 'Spain (2008-12)', 'Support play for one-twos and finishing in the penalty area.', 'Full pitch, 2 keepers, at least 8 outfield players and 3 mannequins near the boxes.', 'Player 1 dribbles at a mannequin, player 7 picks a side to support, they play a 1-2 and player 1 shoots; player 2 then repeats with player 1 supporting, and so on. Shooters run to the other half where a 1-2 is played round a passive defender before shooting. Players rotate positions.', NULL, NULL, NULL, '8+ outfield + 2 GKs', 10, NULL, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 1300),
  ('8v8 (+2) win the ball and one-two to goal', 'small_sided_game', 'overload', 'to_attack', 258, 258, 'Session: Winning the Ball & One-Two Combination High Up the Pitch - Practice 4 (Progression)', 'Spain (2008-12)', 'Using one-twos to get in behind the defensive line and finish after winning the ball.', 'Half pitch: zone from halfway to edge of the box; 3 mini goals on halfway, full goal with keeper at the other end. Reds 2-3-3 v whites 4-4 plus 2 yellow supports for reds.', 'Whites start from their keeper and try to score in the mini goals. Reds press; on winning it they must counter within 6 seconds, with the supports offering 1-2s to break in behind into the end zone (whites may not enter it).', 'Whites 1 point for a side mini goal, 2 for the middle one; reds 1 point for a goal within 6 seconds, 2 if after a 1-2; unlimited touches.', NULL, NULL, '8v8+2 (+GK)', 19, 19, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 1310),
  ('9v9 win the ball and one-two, two goals', 'small_sided_game', 'opposed', 'to_attack', 259, 259, 'Session: Winning the Ball & One-Two Combination High Up the Pitch - Practice 5 (Progression)', 'Spain (2008-12)', 'Winning the ball high and combining with 1-2s in behind to finish quickly.', 'As the 8v8 (+2) game but the 3 mini goals are replaced by a full goal and the 2 supports by 2 keepers; 8v8 outfield with same formations.', 'Same objectives for both teams: whites play out, reds press, win it and use 1-2s round the box to get in behind and finish.', NULL, 'Once the ball enters the end zone all players may go in to attack/defend.', 'Support position and body shape near the box; weight and angle of the first pass; anticipation and quality finishing.', '9v9 incl. GKs', 18, 18, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 1320),
  ('9v9 keeper-to-keeper possession and press', 'transition', 'opposed', 'to_defend', 261, 261, 'Session: Pressing High Up the Pitch: Transition from Defence to Attack - Practice 1', 'Spain (2008-12)', 'Possession with quick transitions from attack to defence and back.', '60 x 40 yard area with a goal and keeper at each end; 9v9 (reds 3-2-3).', 'Reds keep the ball: 1 point for 8 passes, 2 for switching it from one keeper to the other. Whites win it to score 1 for keeping it 6 seconds or 2 for a goal; reds who win it back within 4-6 seconds score 3.', 'Options: all unlimited; reds and keepers 2-3 touches; reds 2 touches and keepers 1.', NULL, NULL, '9v9 incl. GKs', 18, 18, '60 x 40 yards', 54.8, 36.6, NULL, true, true, true, NULL, 1330),
  ('9v7 (+4) high press and counter', 'transition', 'overload', 'to_attack', 262, 262, 'Session: Pressing High Up the Pitch: Transition from Defence to Attack - Practice 2 (Progression)', 'Spain (2008-12)', 'High pressing that blocks passes out wide, then quick counter attacks.', '60 x 40 yard area; reds 8 outfield in a 2-3-3 with keeper; whites 6 inside (4-2) and 4 outside players plus keeper.', 'White keeper starts; when he passes reds press high to stop inside players feeding the outside players and win the ball. Reds must finish within 6 seconds; restart from the white keeper.', 'Whites 1 point for an inside-to-outside pass, 2 for a goal; outside players cannot score; touch options from all unlimited to whites outside 1-2 and reds 2-3.', NULL, NULL, '9v7+4 incl. GKs', 20, 20, '60 x 40 yards', 54.8, 36.6, NULL, true, true, true, NULL, 1340),
  ('Position specific high press and counter game', 'conditioned_game', 'opposed', 'to_attack', 263, 263, 'Session: Pressing High Up the Pitch: Transition from Defence to Attack - Practice 3 (Progression)', 'Spain (2008-12)', 'Collective high pressing and quick counter attacking from a position specific set-up.', 'Full pitch with an extra empty goal 5 yards outside one box; a 10 yard small zone and a high pressing zone marked. Reds 4-3-3, whites 4-4-2.', 'White keeper starts a free game. Reds score 1 for a goal, 2 within 6 seconds of winning it. Whites score 1 for passing in behind into the small zone and 2 for scoring in the empty goal, forcing reds to press quickly.', NULL, NULL, 'Midfield and forwards press together; on the regain make runs in behind for a quick pass and finish within 6 seconds.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 1350),
  ('8v8 continuous transitions with 3 mini goals', 'transition', 'opposed', 'to_attack', 265, 265, 'Session: Pressing High Up the Pitch (2) - Practice 1', 'Spain (2008-12)', 'Transitions from attack to defence and defence to attack.', '60 x 40 yard area: 3 mini goals at one end, a goal line at the other; 8v8 (reds 2-4-2, whites 4-4); 2 coaches with balls at the sides.', 'Scenario 1: a red dribbles in from the goal line to score in a mini goal (side 1 point, middle 2). Then a coach feeds whites, who try to dribble over the goal line (2 points) while reds counter-press and attack again. Scenario 2: reds defend continuously; coaches keep feeding whites from alternate sides and reds press, win it and counter.', NULL, NULL, NULL, '8v8', 16, 16, '60 x 40 yards', 54.8, 36.6, NULL, true, false, true, NULL, 1360),
  ('High intensity 8v8 pressing with empty goals', 'small_sided_game', 'opposed', 'to_defend', 266, 266, 'Session: Pressing High Up the Pitch (2) - Practice 2 (Progression)', 'Spain (2008-12)', 'Pressing the ball carrier immediately on losing possession.', '60 x 40 yard area with 2 full goals and no keepers; both teams 3-2-3 or 2-4-2.', 'Normal game at very high intensity; the moment possession is lost, players close the carrier to deny a shot or pass. Play is continuous: after a goal or ball out, the other team restarts at once.', NULL, NULL, 'Empty goals force instant pressure.', '8v8', 16, 16, '60 x 40 yards', 54.8, 36.6, NULL, true, false, true, NULL, 1370),
  ('Continuous 8v8 transition game, coach feeds', 'transition', 'opposed', 'to_attack', 267, 267, 'Session: Pressing High Up the Pitch (2) - Practice 3 (Progression)', 'Spain (2008-12)', 'Quick transitions both ways in a continuous loop.', '60 x 40 yard area; reds (2-3-3) shoot at a full goal with keeper, whites (4-4) at 3 mini goals; coaches with balls beside the big goal.', 'Part 1: a red dribbles in from the end line and attacks; after the attack a coach feeds a white and reds press high to win it and counter. Part 2: coach always starts with a white, reds press, win and counter; after each red attack the coach feeds another white and the loop continues.', NULL, NULL, NULL, '8v8 + GK', 17, 17, '60 x 40 yards', 54.8, 36.6, NULL, true, true, true, NULL, 1380),
  ('9v9 continuous transition game with shooting zone', 'transition', 'opposed', 'to_attack', 268, 268, 'Session: Pressing High Up the Pitch (2) - Practice 4 (Progression)', 'Spain (2008-12)', 'Pressing in the high zone and fast transitions both ways.', '60 x 40 yard area; a 15 x 40 yard zone at one end with 3 goals defended by a keeper; reds'' full goal and keeper at the other end; coaches feed balls.', 'Whites score 1 for 4 passes, 2 for passing to the red keeper, 3 for entering the end zone, 4 for a mini goal and 5 for the middle goal. Reds get 1 for winning it, 2 for a goal and 3 for scoring within 6 seconds of regaining. Coach feeds whites after every attack.', NULL, NULL, 'Midfield and forwards press together; stay alert for transitions.', '9v9 incl. GKs', 18, 18, '60 x 40 yards', 54.8, 36.6, NULL, true, true, true, NULL, 1390),
  ('11v11 win possession high up the pitch', 'conditioned_game', 'opposed', 'to_defend', 269, 269, 'Session: Pressing High Up the Pitch (2) - Practice 5 (Progression)', 'Spain (2008-12)', 'Pressing in the high zone to regain the ball and attack quickly on a full pitch.', 'Full pitch 11v11 with a marked white attacking end zone; reds 4-3-3 (V midfield), whites 4-4-2 diamond; coaches with balls at the sides.', 'Red keeper starts; reds attack with 2-3 touches. Whites score 1 for keeping the ball 6-8 seconds or 4-6 passes, 2 for reaching the end zone, 3 for a goal. Reds get 1 per goal, 2 within 6 seconds of regaining. Coach feeds whites a new ball after each attack.', 'Reds limited to 2-3 touches.', NULL, 'Midfield and forwards press as a unit; react quickly to every transition.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 1400)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'spain-attacking-sessions-140-practices-from-goal-analysis-of-the-spanish-nationa') b;
